-- Social-Core
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('0b489818-eadc-5d51-ab3e-886f8c5605eb', '7f604bf5-2f90-5f00-9160-30e9265971c4', '1b76e826-b455-4897-8df8-9ace0dff1a64', 'thinking-tool-tinbergen', 'Thinking tool: Tinbergen''s Questions', 'vertical_horizontal', 'A grid for one practice, rule or institution. Rows ask: what is going on now (the situation, rules in force, incentives, the goals and values of the people involved), how people learned it, how it began and changed, what each family added, and what it does for the group and its members'' goals and values. The evolutionary-history row is left out. K-2 and 3-5 use three to five rows. An inside and outside split starts in grade 6.', 'Tinbergen''s Questions in Social-Core. Role in this space: primary. Leads in K-2 and 3-5, where the stages ask about then and now, who taught a rule, how a practice began and spread, and what it is for. It carries Social Change, Culture and Norms across the bands and takes the one large-change case in 9-12. Form: A grid for one practice, rule or institution. Rows ask: what is going on now (the situation, rules in force, incentives, the goals and values of the people involved), how people learned it, how it began and changed, what each family added, and what it does for the group and its members'' goals and values. The evolutionary-history row is left out. K-2 and 3-5 use three to five rows. An inside and outside split starts in grade 6. What it must not bring in: No evolutionary history, genes, hormones or brain mechanisms as causes. No fitness, selection or inheritance. Function means what a practice does for people''s goals and values, and never means that a practice was selected. No program or version lineages.', 'Which of these causes tells us how the rule began, and which tells us why people still keep it?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Barton and Levstik (1996); Kelemen (1999); Dewsbury (1992); Kuhn (2007); Laland et al. (2011); Lira et al. (2024); Kelemen and Rosset (2009); Ariew and Panchanathan (2023). MethodsBase record: OE-METHOD-tinbergens-questions. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["No study found teaches the full grid to children under 11. The K-2 and 3-5 stations rest on studies of time order and picture-book explanations.","Purpose talk is fitting for deliberate rules, but it can hide a different origin. Whether children keep how a rule began apart from why it is kept is untested.","Evidence from school students on the cultural-history, family-history and agency rows is thin."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('7e647b70-e837-5132-9653-2b3df0ada460', '0b489818-eadc-5d51-ab3e-886f8c5605eb', 'ec43321e-dd60-5bd9-bdfc-2e4e17dd7b85', 1, 'K-2, Communities Then and Now (precursor). Children sort picture cards of market day in the town square, long ago and now. They ask an older person what changed and who taught them the market''s ways, and say one reason the market changed. They place the answers on a strip with three boxes: how it is now, who taught it, and what it is for. Example: Market day in the town square, long ago and now. Shown as: Picture cards on a three-box strip: now, who taught it, what it is for. New demand: Put pictures in time order, long ago before now, and say what changed. Splitting who taught it from what it is for is a first try. Evidence for this age is thin. Concepts: Social Change, Culture.', 'd221821a-01a1-54d7-a156-df38866a1dc5', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('dc8e55a6-7cef-5463-a6a0-65ebda131c6a', '0b489818-eadc-5d51-ab3e-886f8c5605eb', 'c4836b7e-c2ac-5eda-9368-08e410453278', 2, 'K-2, Groups We Belong To and Their Rules (precursor). In a circle, children pick one class rule, such as lining up at the door. They answer two picture questions: who taught us this rule, and what would happen to our group without it? A puppet gives a muddled answer that mixes the two, and children sort it out. Example: The class rule of lining up at the door. Shown as: Two large picture question cards, with answer drawings placed under each. New demand: Keep two kinds of answer apart: where the rule came from and what it does for the group. Concepts: Norms, Group.', '380fb2a2-69bf-5950-9997-0b88e441278c', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('bdcebf15-c930-52cd-ac6c-58e49b81526d', '0b489818-eadc-5d51-ab3e-886f8c5605eb', 'aae0bca6-2dfa-5fb1-a2bd-4e8d4381b87c', 3, '3-5, How a Practice Spreads (precursor). Pairs trace a family custom of their choice, such as a holiday dish, onto a five-row grid of sentence cards: what people do now, who taught them, how the custom began and travelled to the family, what their own family added, and what it does for the family. They order the rows from recent to long ago. Example: A family custom the pair chooses, such as a holiday dish or a birthday habit, and how it came to the family. Shown as: Five-row paper grid, sentence cards, rows ordered from recent to long ago. New demand: Add a community-history row and a family-history row, and order rows from recent to long ago without needing dates. Evidence for the full grid at this age is thin. Concepts: Diffusion, Culture, Knowledge.', '1c6776e1-7f70-52c2-8c93-00089fb0056c', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('a54f3d8d-7963-5598-a637-68feacd040e8', '0b489818-eadc-5d51-ab3e-886f8c5605eb', 'f21b382b-ed4a-5e4e-b69b-d603834fbbe9', 4, '3-5, Roles and Why Rules Differ (precursor). Groups compare talking rules in the library and on the playground. They sort given reasons for the difference into grid rows: purpose goes to ''what it does'', history to ''how it began'', group size to ''the situation now''. Each reason names the group and the role of the person who keeps the rule, such as the librarian or the break supervisor. Example: Talking rules in the library and on the playground at break. Shown as: Grid with two columns, one per group, and reason cards sorted into rows. New demand: Sort several given reasons into the right rows and say which question each reason answers. Concepts: Group, Norms, Role.', '7172a165-29d6-5fb9-95e4-8e489b7bdec4', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('96ca9afa-95b2-5b19-ba21-a5edc557a76b', '0b489818-eadc-5d51-ab3e-886f8c5605eb', '9ef944f3-b11a-5327-9082-b53ba736a834', 5, '6-8, How Norms Are Enforced (full). Students apply the grid to queueing at the canteen. The ''now'' row splits into inside (what each student wants, what they think others expect) and outside (who watches, what staff say). They add how queueing was learned and what it does for the group, then say which inside reasons would keep the queue if staff left. Example: Queueing at the school canteen. Shown as: Grid with inside and outside columns in the ''now'' row. New demand: Separate inside reasons from outside pressures, and tell an answer about how things work now from an answer about what the queue does for the group. Concepts: Norms, Incentive, Power.', '380fb2a2-69bf-5950-9997-0b88e441278c', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('ba3c312c-76b9-5e1c-8592-9919929241f6', '0b489818-eadc-5d51-ab3e-886f8c5605eb', 'fd772a6a-0dd8-5410-96c5-79f75443183c', 6, '6-8, Why Societies Differ (full). Students use one grid to explain a difference between two places, such as why Dutch lowland districts keep dikes through water boards while Swiss mountain villages keep shared pasture through village associations. Each row gets one cause and a named piece of evidence. They mark rows where one cause alone fails to explain the difference. Example: Dutch lowland districts keep dikes through water boards. Swiss mountain villages keep shared pasture through village associations. Shown as: One grid with a cause and an evidence note in each row. New demand: Back each cause with named evidence and spot where a single cause fails. Concepts: Culture, Institutions, Knowledge.', '4d0aa77c-9673-5444-9a04-d490aab9f7fc', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('99aec22b-2f2d-5058-a34f-86876a7d8f2a', '0b489818-eadc-5d51-ab3e-886f8c5605eb', '504c7645-bc71-5a81-a114-cd2d598d1621', 7, '9-12, Explaining Large-Scale Change (extended). Students take a large change over generations, such as votes for women in Germany, and fill the grid with inside and outside factors for each row, marking rows that do not apply. They rank rows by weight of evidence, swap with a partner who critiques the ranking, and write where a single-cause story fails. Example: Votes for women in Germany: decreed in November 1918, first used in January 1919. Shown as: Full grid with inside and outside columns, an evidence column and a ranking of rows. New demand: Weigh rows against each other on evidence and argue against a single-cause story. Concepts: Social Change, Agency, Power, Institutions.', 'd221821a-01a1-54d7-a156-df38866a1dc5', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('e5579972-a3f8-5f43-a688-314236c4d68d', '7f604bf5-2f90-5f00-9160-30e9265971c4', '1b76e826-b455-4897-8df8-9ace0dff1a64', 'thinking-tool-causal', 'Thinking tool: Causal Mapping', 'vertical_horizontal', 'A map of factors joined by arrows: actions, rules, resources, expectations and group outcomes. An arrow means makes more likely or makes less likely. In a cycle, each arrow carries a reason people act on. From grade 3 students find cycles of people responding to each other, such as advantage piling up or a norm spiral. Delays and named patterns such as the Tragedy of the Commons start in grade 6. Population, homeostasis, feedback and data-flow words are left out.', 'Causal Mapping in Social-Core. Role in this space: primary. Leads in 6-8 and 9-12, where the stages ask how norms are kept up or lost, why each person''s best choice can harm a group, and how power and institutions change a society over generations. It also carries Incentive, Norms and Power across bands. Form: A map of factors joined by arrows: actions, rules, resources, expectations and group outcomes. An arrow means makes more likely or makes less likely. In a cycle, each arrow carries a reason people act on. From grade 3 students find cycles of people responding to each other, such as advantage piling up or a norm spiral. Delays and named patterns such as the Tragedy of the Commons start in grade 6. Population, homeostasis, feedback and data-flow words are left out. What it must not bring in: No population growth, births, homeostasis or thermostat comparisons. No input, state, data flow, feedback or training words. A cycle is described as what people do in response to each other, with a reason on each arrow. No genes or selection as an arrow label.', 'If everyone does this, what happens next, and does that make the next person more or less likely to do it?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Gopnik et al. (2004); Schulz and Gopnik (2004); Danish (2014); Grotzer and Basca (2003); Kuhn (2007); Ben-Zvi Assaraf and Orion (2010); Sweeney and Sterman (2007); Ben-Zvi Assaraf and Orion (2005); Chi et al. (2012); Sweeney and Sterman (2000); Resnick (1996). MethodsBase record: OE-METHOD-causal-mapping. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["No study found tests arrows, loops or delays in causal maps with children under 8. The K-2 station rests on studies of how young children learn causes.","Evidence on drawing and reading loops comes mostly from middle school and adult samples.","Most systems-thinking studies use ecosystems or the water cycle. Maps of social cycles are untested with school students.","The project''s own causal-mapping teaching paper (S10) was not read in full, so no station cites it.","Keeping cycles is a design choice about the Social-Core boundary: each arrow must carry a reason people act on. No study tests this with school students."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('4e0a457b-0310-5f97-9fe9-42fcc347899b', 'e5579972-a3f8-5f43-a688-314236c4d68d', 'f7608bc0-18ff-52e5-8238-ac0220214ec9', 1, 'K-2, Sharing and Taking Turns (precursor). Children act out a story with three picture cards: one child keeps the ball, the others stop inviting her, she plays alone. They lay the cards in a row and join them with floor arrows that say ''because''. Then they add a fourth card showing what the group could do. Example: One child keeps the ball, so the others stop inviting her. Shown as: Picture cards in a row joined by floor arrows that say ''because''. New demand: Link events in a chain, so each result becomes the cause of the next card. Loops are untested at this age. Concepts: Cooperation, Conflict, Norms.', 'd7094e85-8ed0-5b69-b6e3-5fcf954eb582', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('36dd77fa-df1c-5910-9d9d-bdb486703f40', 'e5579972-a3f8-5f43-a688-314236c4d68d', '3d964122-338c-548e-882b-d833d2ec4209', 2, '3-5, Why People Cooperate or Hold Back (full). Groups read a story about a class party table where some children bring cakes and others do not. Each cause goes on a card: a thank-you from the teacher, trust in friends, talking beforehand. Arrows labelled ''the more... the more...'' join every cause to ''children bring cakes''. Example: Who brings a cake to the class party table. Shown as: Cards with ''the more... the more...'' arrows, several arrows pointing at one outcome. New demand: Draw two or more causes into one effect and label the direction of each arrow. Concepts: Cooperation, Incentive, Communication.', 'd7094e85-8ed0-5b69-b6e3-5fcf954eb582', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('2c85b316-506a-57a2-b3a4-cce903ae1b33', 'e5579972-a3f8-5f43-a688-314236c4d68d', 'aae0bca6-2dfa-5fb1-a2bd-4e8d4381b87c', 3, '3-5, How a Practice Spreads (full). Students map how a recycling habit spread from one class to the whole school. Cards: one class recycles, other classes see the bins, more classes try. They draw an arrow from ''more classes recycle'' back to ''more classes see it'', write the reason people act on each arrow, call it a building-up cycle, and add one cause that could slow it. Example: A recycling habit spreading from one class to the whole school. Shown as: Cards with labelled arrows, a reason on each arrow, and one curved return arrow marked as a building-up cycle. New demand: Close a cycle: draw an arrow from an effect back to its own cause, and write the reason people act on at each arrow. Concepts: Diffusion, Culture.', '1c6776e1-7f70-52c2-8c93-00089fb0056c', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('ce89ffa8-4047-5250-a3ff-8fbe7ef04f42', 'e5579972-a3f8-5f43-a688-314236c4d68d', '9ef944f3-b11a-5327-9082-b53ba736a834', 4, '6-8, How Norms Are Enforced (full). Students map a school-yard rule about litter. Factors: monitors checking, friends frowning, litter on the ground, effort to reach a bin. They mark which cycles build up and which settle, write the reason people act on each arrow, and predict what follows if monitors stop checking. Example: Keeping the school yard litter-free once monitors stop checking. Shown as: Map with same-way and opposite-way arrows, a reason on each arrow, cycles labelled builds up or settles. New demand: Tell cycles that build up from cycles that settle, with the reason people act on at each arrow. Delays wait for the next station. Concepts: Norms, Incentive, Power.', '380fb2a2-69bf-5950-9997-0b88e441278c', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('ef6a072e-e797-5ec9-bbb3-5aa3253d7521', 'e5579972-a3f8-5f43-a688-314236c4d68d', '2de4fac1-1590-5260-a501-d040c57c2acf', 5, '6-8, Shared-Resource Problems (full). Students map the garden club''s water tank in a dry summer. They link each member''s water use, the tank level, each member''s gain and the shortage all share, mark the delay between heavy use and an empty tank, and name the Tragedy of the Commons pattern. Then they circle two places where a change would help and say what each costs. Example: A garden club sharing one water tank in a dry summer. Shown as: Map with arrows, a delay mark, a named pattern and two circled places to intervene. New demand: Place a delay, name a known pattern and choose places to intervene, with their costs. Concepts: Collective Action, Incentive, Cooperation.', 'da192735-7ddb-59aa-937b-4090a3073862', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('4d0d7242-f2d4-5568-a24c-8a3037f7047d', 'e5579972-a3f8-5f43-a688-314236c4d68d', 'e0e725b5-1716-5f38-95d7-bdaa1297f892', 6, '9-12, Governing Shared Resources: Power and Conflict (extended). Students map two clubs sharing a sports hall, where the bigger club''s say over bookings grows with its resources. They mark the cumulative advantage pattern, add a second cycle through which the smaller club can respond, such as recruiting members, and rank places to intervene by expected effect. Example: Two clubs sharing a sports hall, where the bigger club gains more say. Shown as: Map with several cycles, delays, one named pattern and numbered places to intervene. New demand: Link two cycles that pull against each other and rank places to intervene with reasons. Concepts: Power, Conflict, Institutions.', '834c8631-d832-5ddc-81f8-828686900d33', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('93582ae8-947c-5387-8543-12d3c90ae875', 'e5579972-a3f8-5f43-a688-314236c4d68d', '504c7645-bc71-5a81-a114-cd2d598d1621', 7, '9-12, Explaining Large-Scale Change (extended). Students map the rise of trade unions in industrial towns over several generations: organising, bargaining power, new laws, employers'' responses and public opinion, with delays marked. They check the map against two sources and tag each arrow as supported, disputed or a guess. Example: Trade unions growing in industrial towns over generations. Shown as: Map with delays and an evidence tag on every arrow. New demand: Tag each arrow with the evidence behind it and say which arrows are guesses. Concepts: Social Change, Agency, Power, Institutions.', 'd221821a-01a1-54d7-a156-df38866a1dc5', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('8b1dea35-4855-5ae1-a99c-e258ac1513c2', '7f604bf5-2f90-5f00-9160-30e9265971c4', '1b76e826-b455-4897-8df8-9ace0dff1a64', 'thinking-tool-payoff', 'Thinking tool: Payoff Matrices', 'vertical_horizontal', 'A table that sets one person''s or group''s choices against another''s. Each cell says what each side gets or pays, now and later, as the people involved would judge it. Choices are made for reasons and under rules. The question is whether a dilemma exists and what could change it: talking, trust, new rules or institutions. Fitness, learning agents and programs are left out.', 'Payoff Matrices in Social-Core. Role in this space: primary. Introduces the two-party table in 3-5 and carries the dilemma in 6-8 and 9-12, where the stages ask why each person''s best choice can leave the group worse off and how power and institutions change the options. It also carries Incentive, Cooperation and Conflict. Form: A table that sets one person''s or group''s choices against another''s. Each cell says what each side gets or pays, now and later, as the people involved would judge it. Choices are made for reasons and under rules. The question is whether a dilemma exists and what could change it: talking, trust, new rules or institutions. Fitness, learning agents and programs are left out. What it must not bring in: No fitness, evolutionarily stable strategies or learning-agent talk. Payoffs are costs and benefits that people judge. They are never reproductive success. No program that chooses for itself. A way out comes from talk, trust, rules or institutions. No biological or machine games as evidence.', 'What does each person get from each pair of choices, now and later, and what could change the table?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Fehr et al. (2008); Blake and McAuliffe (2011); House et al. (2013); Flobbe et al. (2008); Sutter et al. (2019); Steinbeis et al. (2012); Hedden and Zhang (2002); Steinberg et al. (2009). MethodsBase record: OE-METHOD-payoff-matrices. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["No study found tests whether students can spot a social dilemma from a payoff table. The nearest evidence is on fairness choices, rational choice, delay and strategic play.","Costly sharing differs by culture and age, so one class''s play may differ from published figures. Saxony classes are untested.","The K-2 outcome cards have no direct evidence. They rest on fairness-choice studies with children aged 3 to 8."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('579ef300-14be-5faa-ad05-3dd4ea594495', '8b1dea35-4855-5ae1-a99c-e258ac1513c2', 'f7608bc0-18ff-52e5-8238-ac0220214ec9', 1, 'K-2, Sharing and Taking Turns (precursor). Two children and one tub of blocks, acted out with puppets. For each choice, share or keep, children place a happy or sad face for the child who chose and one for the other child. They read the faces aloud and say whether the turn was fair. Example: Sharing a tub of building blocks, or keeping it. Shown as: One-choice outcome cards with two faces each, one for me and one for my partner. New demand: See that one choice affects two people and read both outcomes. A true table is held back to grade 3. Concepts: Cooperation, Conflict, Norms.', 'd7094e85-8ed0-5b69-b6e3-5fcf954eb582', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('d54a88ec-e952-548b-812f-6e4726e6cf32', '8b1dea35-4855-5ae1-a99c-e258ac1513c2', '3d964122-338c-548e-882b-d833d2ec4209', 2, '3-5, Why People Cooperate or Hold Back (full). Groups play a short passing game, then fill a two-by-two table: I pass or keep, my teammate passes or keeps. Each cell has a sentence for each player. They circle the cell they expect before and after the pair talks, and name an incentive and a sign of trust. Example: Passing the ball or keeping it in a school football game. Shown as: Two-by-two paper table with sentence cells and picture cues for each choice. New demand: Use both players'' choices at once and say what each expects the other to do. Evidence is thin at this age. Concepts: Cooperation, Incentive, Communication.', 'd7094e85-8ed0-5b69-b6e3-5fcf954eb582', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('371d8cec-d27a-529b-9695-76e889c74045', '8b1dea35-4855-5ae1-a99c-e258ac1513c2', 'fd772a6a-0dd8-5410-96c5-79f75443183c', 3, '6-8, Why Societies Differ (full). Students build a table for two neighbouring societies choosing which side of the road to drive on. Both sides work if everyone matches. They see that this table holds no dilemma, then use history to explain why Britain and France ended up with different conventions and why Sweden changed in 1967. Example: Which side of the road to drive on: Britain and France, and Sweden''s change in 1967. Shown as: Two-by-two table where matching cells are good and mismatched cells are poor. New demand: Tell a table with no dilemma from one with a dilemma, and explain a difference between societies through history. Concepts: Culture, Norms, Institutions.', '4d0aa77c-9673-5444-9a04-d490aab9f7fc', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('266dfad0-7f73-5206-a97b-cf1b664d1e08', '8b1dea35-4855-5ae1-a99c-e258ac1513c2', '2de4fac1-1590-5260-a501-d040c57c2acf', 4, '6-8, Shared-Resource Problems (full). Students build a two-by-two table for two garden-club members who each use a lot or a little water, with rows for this summer and next summer. They find the cell where each person''s best choice leaves both worse off, then redo the table after a quota or a talk and note the cost of each fix. Example: Two garden-club members sharing one water tank. Shown as: Two-by-two table with this-summer and next-summer rows; a second table after a change. New demand: Add the long-term row and find the dilemma cell. Evidence for reading such a table at this age is thin. Concepts: Collective Action, Incentive, Conflict, Cooperation.', 'da192735-7ddb-59aa-937b-4090a3073862', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('db99d35e-12fd-59bf-8717-08f6c36197e8', '8b1dea35-4855-5ae1-a99c-e258ac1513c2', '56eb4828-57c2-589b-92ba-180f901b2443', 5, '9-12, Formal Institutions and Informal Norms (extended). Students draw two tables in which one person and everyone else each drop a drink bottle or return it: before a deposit system and after. They shade the cells the deposit changes, compare what each institution does to the incentive, and say who pays for keeping it going. Example: A deposit on drink bottles changes what leaving one on the ground costs. Shown as: Two tables side by side, changed cells shaded, plus a column for the cost of enforcement. New demand: Show how an institution changes payoffs, then ask who pays to keep it running. Concepts: Institutions, Incentive, Agency.', '4e1ba9af-f7f2-5a32-b3c5-83baca7d1265', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('03f483ef-4f38-5478-9098-5663fe6c4ca3', '8b1dea35-4855-5ae1-a99c-e258ac1513c2', 'e0e725b5-1716-5f38-95d7-bdaa1297f892', 6, '9-12, Governing Shared Resources: Power and Conflict (extended). Students build a table for upstream and downstream villages sharing a river, where upstream can hold back water and downstream cannot. They set it beside an equal-options table, shade the cells that power changes, and test which rule, monitor or authority would shift the outcome. Example: Upstream and downstream villages sharing a river''s water. Shown as: Two tables, equal and unequal options, with cells shaded where power shifts the outcome. New demand: Give each side different options and trace how power shapes the outcome. Concepts: Power, Conflict, Collective Action, Institutions.', '834c8631-d832-5ddc-81f8-828686900d33', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('16f9d8f8-fbd1-5f76-beba-e4c1f39c73c6', '7f604bf5-2f90-5f00-9160-30e9265971c4', '1b76e826-b455-4897-8df8-9ace0dff1a64', 'thinking-tool-analogy', 'Thinking tool: Analogy Mapping', 'vertical_horizontal', 'Two social cases side by side, shared structure in rows (who decides, what the rule is, how it is enforced, what people gain), and a where-it-breaks column. Breaks are named in terms of beliefs, power and institutions. Both cases are social: two groups, two institutions, or a classroom game and the situation it stands for. Biological and machine cases are left out.', 'Analogy Mapping in Social-Core. Role in this space: supporting. Appears in every band and leads none. The stages already ask students to compare groups, rules, societies and designs. Analogy maps make that comparison explicit and add the break column. It carries Group, Role, Norms and Institutions. Form: Two social cases side by side, shared structure in rows (who decides, what the rule is, how it is enforced, what people gain), and a where-it-breaks column. Breaks are named in terms of beliefs, power and institutions. Both cases are social: two groups, two institutions, or a classroom game and the situation it stands for. Biological and machine cases are left out. What it must not bring in: No biological examples as evidence, such as honeybee swarms, cells or immune systems. No taste-bud or machine comparisons. The Guide''s biological column is dropped. No selection or fitness as shared structure. Break points use beliefs, power and institutions.', 'Which rows match, and where does the comparison stop working: in what people believe, who holds power, or which institution is involved?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Goswami and Brown (1990); Kotovsky and Gentner (1996); Loewenstein and Gentner (2005); Richland et al. (2006); Gentner and Toupin (1986); Alfieri et al. (2013); Gentner (1988); Coll et al. (2005); Grosslight et al. (1991); Schwarz et al. (2009); Spiro et al. (1989); Gick and Holyoak (1983); Gentner (1983). MethodsBase record: OE-METHOD-analogy-mapping. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["Naming where an analogy breaks is untested with children under 11. The K-2 station holds it back and the 3-5 stations ask for one difference.","Evidence for mapping two cases and naming break points with school students is thin. Adult studies support the two-case design.","Look-alike details distract younger children, so row labels need relational words.","The case pairs are drafted for Saxony classes and have not been checked for accuracy.","The design principles used as rows in the 9-12 station come from the Teacher''s Guide and are not among the 78 verified sources. They are a teaching checklist and have no classroom test."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('6d6f483a-474d-577d-bf2f-344c562c03fd', '16f9d8f8-fbd1-5f76-beba-e4c1f39c73c6', 'c4836b7e-c2ac-5eda-9368-08e410453278', 1, 'K-2, Groups We Belong To and Their Rules (precursor). Children place picture cards of rules from home and from the music class in two columns. They draw a string between two rules that do the same job, such as ''wait for your turn'', and say ''same job'' or ''different job''. They then pick one rule that differs. Example: Rules at the dinner table and in the music class. Shown as: Two picture columns with string lines between matching rules. New demand: Match by the job a rule does and ignore what the picture looks like. Naming a break is held back to grade 3. Concepts: Group, Norms.', '7172a165-29d6-5fb9-95e4-8e489b7bdec4', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('b0f6fc05-c636-54a6-a283-6fac5fe91221', '16f9d8f8-fbd1-5f76-beba-e4c1f39c73c6', 'f21b382b-ed4a-5e4e-b69b-d603834fbbe9', 2, '3-5, Roles and Why Rules Differ (full). Pairs map one person''s role in two groups, for example a girl who is goalkeeper on her team and the oldest sibling at home. Rows: what the group expects, who tells her, what happens if she does not do it. A last column asks where the two roles do not match. Example: A child who is goalkeeper at football and the oldest sibling at home. Shown as: Two-column table with three shared rows and a column headed where it does not match. New demand: Add the break column: name one thing that differs and say why. Concepts: Role, Group, Norms.', '1b24284c-8f34-57b5-83bc-0b21e990d1e7', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('08986d21-7b68-5145-b5ff-2c3242825d19', '16f9d8f8-fbd1-5f76-beba-e4c1f39c73c6', 'aae0bca6-2dfa-5fb1-a2bd-4e8d4381b87c', 3, '3-5, How a Practice Spreads (full). Students compare how a bread recipe and a marbles game each reached a new town. Rows: who carried it, what contact spread it, why people took it up. They then ask where the two routes differ, for example who carried each one. Example: How a bread recipe and a marbles game each reached a new town. Shown as: Two-column table with three shared rows and one row for differences. New demand: Pick rows that match by role in the story, such as carrier and contact, and skip look-alike details. Concepts: Diffusion, Knowledge, Communication.', '1c6776e1-7f70-52c2-8c93-00089fb0056c', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('f13d7668-ac2a-5f9b-920c-516b7cda8d87', '16f9d8f8-fbd1-5f76-beba-e4c1f39c73c6', '9ef944f3-b11a-5327-9082-b53ba736a834', 4, '6-8, How Norms Are Enforced (full). Students compare silence in an exam hall, kept by an invigilator, with quiet in a cinema, kept by neighbours'' looks. Rows: who sets the expectation, how breaches are noticed, what follows. They name where the comparison breaks in terms of who holds power and what each person believes. Example: Silence in an exam hall and quiet in a cinema. Shown as: Two-column map with shared rows and a break column; each break labelled belief, power or institution. New demand: Label each break as a matter of belief, power or institution. Concepts: Norms, Power, Institutions.', '380fb2a2-69bf-5950-9997-0b88e441278c', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('d890ba4e-f55d-5063-b460-0ddd04ce2ee2', '16f9d8f8-fbd1-5f76-beba-e4c1f39c73c6', '2de4fac1-1590-5260-a501-d040c57c2acf', 5, '6-8, Shared-Resource Problems (full). Students play a token-sharing game, then map it against the shared-resource problem it stands for. Rows cover who gains, who loses and what each could do. The break column lists what the game leaves out, such as history, trust built over years and who can punish. Example: A classroom token-sharing game and the upkeep of a shared school common room, where each user can leave the tidying to others. Shown as: Two-column map, game and case, with a break column listing what the game leaves out. New demand: Treat the game as a built model with named gaps. Concepts: Collective Action, Cooperation, Incentive.', 'da192735-7ddb-59aa-937b-4090a3073862', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('70c78a04-5c9a-5c71-8e3b-0afadca7e25b', '16f9d8f8-fbd1-5f76-beba-e4c1f39c73c6', '56eb4828-57c2-589b-92ba-180f901b2443', 6, '9-12, Formal Institutions and Informal Norms (extended). Students compare how two institutions pursue the same aim: fair grading under a central exam board and under each teacher''s own marks. Rows: who decides, who checks, how complaints are handled, whom it favours. They rank the breaks by how much each changes the outcome and give evidence. Example: Fair grading under a central exam board and under each teacher''s own marks. Shown as: Two-column map with four shared rows, a break column and a ranking of the breaks. New demand: Rank the breaks by how much each changes the outcome, and defend the ranking with evidence. Concepts: Institutions, Incentive, Power.', '4e1ba9af-f7f2-5a32-b3c5-83baca7d1265', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('7326f9f4-5ba4-516e-ae5e-8851d7d891b5', '16f9d8f8-fbd1-5f76-beba-e4c1f39c73c6', 'e0e725b5-1716-5f38-95d7-bdaa1297f892', 7, '9-12, Governing Shared Resources: Power and Conflict (extended). Students use five design principles from the Teacher''s Guide as rows: shared goals, fair costs, fair decisions, monitoring and conflict resolution. They map a village water council against an international climate agreement and mark where each principle holds, weakens or breaks, and why. Example: A village water council and an international climate agreement, both governing a shared resource. Shown as: Two-column map with design principles as rows and a break column. New demand: Use a given set of principles as rows, judge where size and distance weaken each one, and label each break as belief, power or institution. Concepts: Collective Action, Institutions, Power, Conflict.', 'da192735-7ddb-59aa-937b-4090a3073862', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

UPDATE projects SET introduction = introduction || '

Thinking tools. Four OpenEvo thinking tools (Tinbergen''s Questions, Causal Mapping, Payoff Matrices and Analogy Mapping) are deployed across the grade bands of this space as four threads named "Thinking tool: ...". Social-Core explains why groups cooperate, conflict, hold rules and change, using goals, rules, roles, incentives and power. The four tools fit that aim. Tinbergen''s grid sorts the reasons, teaching, history and purposes behind a practice. Payoff tables show how incentives pull people and groups apart. Causal maps show how actions and rules feed each other over time. Analogy maps compare groups and institutions. The boundary rules out selection, fitness, inheritance, computing terms, and biological or machine cases as evidence. K-2: Tinbergen leads, with picture cards on then and now, who taught a rule and what it is for. 3-5: Tinbergen adds practice and family history, Payoff brings the first two-party table and Causal Mapping closes the first cycle. 6-8: Payoff finds the dilemma and Causal Mapping follows its cycles. 9-12: Payoff and Causal Mapping weigh institutions and power, Tinbergen sorts the causes of one large change and Analogy compares institutions. Analogy appears in every band. The threads have the status proposed. AI drafted them and no subject expert has reviewed them.' WHERE id = '7f604bf5-2f90-5f00-9160-30e9265971c4' AND introduction NOT LIKE '%Thinking tools. Four OpenEvo thinking tools%';

