SELECT '7f604bf5-2f90-5f00-9160-30e9265971c4', 'OE-LITERATURE-kelemen-2009', 'The Human Function Compunction: Teleological explanation in adults', '["Kelemen, Deborah","Rosset, Evelyn"]'::jsonb, 2009, '10.1016/j.cognition.2009.01.001', 'Cognition', 'article', 'draft', 'Evidence for the thinking-tool threads of Social-Core (AI-drafted 2026-10-26, no expert review). Undergraduates judging explanations under time pressure accepted more scientifically unwarranted purpose-based explanations as correct.', ARRAY['thinking-tools', 'proposed-link']::text[]
WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = '7f604bf5-2f90-5f00-9160-30e9265971c4' AND literaturebase_id = 'OE-LITERATURE-kelemen-2009');
