SELECT '7f604bf5-2f90-5f00-9160-30e9265971c4', 'OE-LITERATURE-ariew-panchanathan-2023', 'Adding Agency to Tinbergen''s Four Questions', '["Ariew, André","Panchanathan, Karthik"]'::jsonb, 2023, '10.1007/978-3-031-33358-3_21', 'Evolutionary Thinking Across Disciplines: Problems and Perspectives in Generalized Darwinism (Synthese Library, A. du Crest, M. Valković, A. Ariew, H. Desmond, P. Huneman, & T. A. C. Reydon, Eds.)', 'chapter', 'draft', 'Evidence for the thinking-tool threads of Social-Core (AI-drafted 2026-10-26, no expert review). Proposes adding agency to the four questions and is named by the project lead as a source of the expanded grid; not read here.', ARRAY['thinking-tools', 'proposed-link']::text[]
WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = '7f604bf5-2f90-5f00-9160-30e9265971c4' AND literaturebase_id = 'OE-LITERATURE-ariew-panchanathan-2023');
INSERT INTO literature_references (project_id, literaturebase_id, title, authors, year, doi, venue, type, status, notes, tags)
SELECT '7f604bf5-2f90-5f00-9160-30e9265971c4', 'OE-LITERATURE-resnick-1996', 'Beyond the Centralized Mindset', '["Resnick, Mitchel"]'::jsonb, 1996, '10.1207/S15327809JLS0501_1', 'Journal of the Learning Sciences', 'article', 'draft', 'Evidence for the thinking-tool threads of Social-Core (AI-drafted 2026-10-26, no expert review). People often assume centralized control where none exists, as seen in high-school students'' StarLogo projects.', ARRAY['thinking-tools', 'proposed-link']::text[]
WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = '7f604bf5-2f90-5f00-9160-30e9265971c4' AND literaturebase_id = 'OE-LITERATURE-resnick-1996');
INSERT INTO literature_references (project_id, literaturebase_id, title, authors, year, doi, venue, type, status, notes, tags)
SELECT '7f604bf5-2f90-5f00-9160-30e9265971c4', 'OE-LITERATURE-gick-holyoak-1983', 'Schema induction and analogical transfer', '["Gick, Mary L.","Holyoak, Keith J."]'::jsonb, 1983, '10.1016/0010-0285(83)90002-6', 'Cognitive Psychology', 'article', 'draft', 'Evidence for the thinking-tool threads of Social-Core (AI-drafted 2026-10-26, no expert review). Classic adult study of how comparing analogous cases builds a schema that supports transfer; the abstract was not retrieved.', ARRAY['thinking-tools', 'proposed-link']::text[]
