INSERT INTO literature_references (project_id, literaturebase_id, title, authors, year, doi, venue, type, status, notes, tags)
SELECT '7f604bf5-2f90-5f00-9160-30e9265971c4', 'OE-LITERATURE-gentner-1983-structure-mapping', 'Structure-Mapping: A Theoretical Framework for Analogy', '["Gentner, Dedre"]'::jsonb, 1983, '10.1207/s15516709cog0702_3', 'Cognitive Science', 'article', 'draft', 'Evidence for the thinking-tool threads of Social-Core (AI-drafted 2026-10-26, no expert review). Theory that analogies map relations between objects and prefer systems of connected relations over object attributes.', ARRAY['thinking-tools', 'proposed-link']::text[]
WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = '7f604bf5-2f90-5f00-9160-30e9265971c4' AND literaturebase_id = 'OE-LITERATURE-gentner-1983-structure-mapping');

-- Computational-Core
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('84b90df6-6798-5a44-8119-da1e581f3df2', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '3eceaf9b-fb08-4821-ba31-77f3b3f478d2', 'thinking-tool-tinbergen', 'Thinking tool: Tinbergen''s Questions', 'vertical_horizontal', 'Five questions about one behaviour of a system. Mechanism: inputs, stored values and rules behind the output. Development: design choices, training data, settings and updates. Function: what it was built to do, what it measurably does and for whom. Version history: code copied and changed, and versions people keep or withdraw. Loop: what users and builders observe feeds the next version. A column for inside and outside factors appears at 9-12 only. Cultural and family history rows are left out.', 'Tinbergen''s Questions in Computational-Core. Role in this space: supporting. Studies of children cover single skills, and the machine-behaviour papers address researchers. The questions help students keep four kinds of answer apart, so they support the other tools in every band and take a shared lead only at 9-12. Form: Five questions about one behaviour of a system. Mechanism: inputs, stored values and rules behind the output. Development: design choices, training data, settings and updates. Function: what it was built to do, what it measurably does and for whom. Version history: code copied and changed, and versions people keep or withdraw. Loop: what users and builders observe feeds the next version. A column for inside and outside factors appears at 9-12 only. Cultural and family history rows are left out. What it must not bring in: No organism terms such as genes, fitness or reproduction. No wants, beliefs or understanding in a machine. Training adjusts numbers using data that people chose. Purposes belong to builders and users. Versions continue because people copy, change and keep them.', 'Which of these answers says how the system works now, which says how this version was built, and which says what it is for and for whom?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Levy and Mioduser (2008); Mioduser et al. (2009); Bernstein and Crowley (2008); Dewsbury (1992); Swidan et al. (2018); Shtulman et al. (2016); Barton and Levstik (1996); Rahwan et al. (2019); Keil (2006); Lira et al. (2024); Brinkmann et al. (2023); Schwarz et al. (2009). MethodsBase record: OE-METHOD-tinbergens-questions. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["No study found teaches the questions to children under 11. The K-2 and 3-5 stations rest on studies of component skills.","Rahwan et al. group the questions as how versus why, a grouping the project deck criticizes. This space asks them as parallel questions.","Brinkmann et al. were read as a preprint and never mention Tinbergen. The version-history and loop questions lean on them for the copy-and-keep idea only.","Neither machine paper grounds the inside and outside split. It appears at 9-12 only, as a drafting choice.","Source S72 is cited from its title only, in the K-2 station. Its abstract could not be retrieved."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('94c6375b-e7de-5420-8801-581da6a19566', '84b90df6-6798-5a44-8119-da1e581f3df2', '04edbe9b-292d-5101-a009-fc46ead81427', 1, 'K-2, Machines Follow Rules People Write (precursor). Children look at a classroom timer that rings a bell. They sort answer cards under three question cards: What rule makes it ring? Who set the rule? What is it for? Then they change the set time and watch the ring move. Example: A classroom timer that rings a bell at a set time. Shown as: Three question cards, answer cards to sort, and a picture of the timer. New demand: Sorts answers into three kinds of because. Some children may answer ''what rule?'' with what the timer is for, so the teacher asks again for the rule. Concepts: Program, Algorithm.', 'd5b9a8e1-3f8d-5100-9a23-b4d0aae498f9', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('c04cd4bf-85e1-519a-97e1-633bc6dc1765', '84b90df6-6798-5a44-8119-da1e581f3df2', '8c7bc083-021f-5891-b502-de2f708a1e09', 2, '3-5, Sequences, Loops and Conditions (precursor). A class poll program shows last week''s totals after an update. Students answer three questions on a card. Mechanism: which stored values and steps produced the totals, found by tracing. Development: what changed between version 1 and version 2. Function: what the poll is for and who reads it. Example: A class poll program that shows last week''s totals after an update. Shown as: A three-row answer card beside a table of traced values and a version log. New demand: Keeps two causes apart: the rule running now and the edit made earlier. Time spans stay concrete, one run and one week of edits. Concepts: Program, State, Algorithm.', 'd5b9a8e1-3f8d-5100-9a23-b4d0aae498f9', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('6dd0a33f-20ff-5758-b137-3a00d4847363', '84b90df6-6798-5a44-8119-da1e581f3df2', 'f95b2dff-2e43-597e-b8c6-a1857c0f60c7', 3, '3-5, Recording and Charting Data (precursor). Students take a chart from a school newsletter and ask three things. How was each bar made from the table? How and when were the data collected? Who made the chart, for whom, and what does it leave out? Example: A newsletter chart of favourite lunches used to plan the menu. Shown as: A paper chart with sticky notes sorted into the three question types. New demand: Applies the questions to an object that other people made, so function includes who it serves and what it hides. Concepts: Data, Representation, Abstraction.', 'e49e585b-b47d-553f-adff-0381568f4589', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('7de9b566-f7b2-560d-a7e7-1ad537714368', '84b90df6-6798-5a44-8119-da1e581f3df2', '31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', 4, '6-8, Decomposition, Functions and Testing (full). Students open the remix history of a shared block program: the original, two copies and a copy of a copy. For each version they answer: which blocks make it run, what changed from its parent (a function split out, for example), and what is it for. They then ask which versions people copied, kept or withdrew, and why. Example: The remix tree of a shared maze-game project. Shown as: A tree of versions on paper, each version labelled with its changed functions. New demand: Adds the version-history question: which code was copied or changed, by whom, and why people chose to copy it. Concepts: Program, Decomposition.', 'd5b9a8e1-3f8d-5100-9a23-b4d0aae498f9', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('39b555fb-4588-5f9f-bb1c-fa6fcdb770cf', '84b90df6-6798-5a44-8119-da1e581f3df2', '45c484c9-e753-5bb3-86af-086bc28fce31', 5, '6-8, Agent-Based and Feedback Models (full). Students take one pattern from an agent-based model. They answer four questions. Which rule and setting produce it now? How did the rule and settings change across our runs? What question is the model meant to answer, and for whom? What did an earlier version of the model show? Example: Buses bunching together in a model of buses on one route. Shown as: A four-row question card beside a run log of settings and screenshots of the pattern. New demand: Keeps rules and settings apart as two kinds of cause, and adds the model''s own version history. Concepts: Model, Simulation, Feedback, State.', 'ea8aba67-5ef6-59cd-9f1f-6198c3966353', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('5e1e7064-4a4e-59fe-ac6b-b2e03ba0836f', '84b90df6-6798-5a44-8119-da1e581f3df2', 'e6374470-9533-570e-8d98-0e5b24060f4d', 6, '9-12, Machine Learning, Search and Distributed Systems Compared (extended). Students ask all five questions of a video recommender. Mechanism: the ranking rule and stored history. Development: training data, settings and updates. Function: the engagement objective and possible side effects such as filter bubbles. Version history: earlier methods and what stayed. Loop: clicks return as training data. They then state what the system does without wants or understanding. Example: A video recommender that is retrained each week on what people clicked. Shown as: A five-row grid. A second column, added last, separates factors inside the system from factors outside it. New demand: Uses all five questions including the loop through people, and writes each answer without intention words. Concepts: Machine Learning, Feedback, Data, Model.', '63046d12-d8d7-5830-b2df-ac2833e913f0', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('3f50b6d2-e172-5d6b-9fad-ff10091788da', '84b90df6-6798-5a44-8119-da1e581f3df2', 'e6374470-9533-570e-8d98-0e5b24060f4d', 7, '9-12, Machine Learning, Search and Distributed Systems Compared (extended). Students apply the questions to a route app that suggests a side street. Mechanism: a search over a stored map with an objective. Development: map updates and objective settings. Function: fastest for whom, and the effect on side streets. Version history: older route-finding methods that newer ones reuse. They then state what the app can be said to do without intention. Example: A route app that sends drivers down a quiet side street. Shown as: A five-row grid beside the map and the stored objective setting. New demand: Asks what the objective leaves out and names effects on people who never used the system. Concepts: Search, Algorithm, Specification.', '244aa554-5721-559e-be7e-4e3d4331e644', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('b1e529a5-f584-5647-8858-db2871318297', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '3eceaf9b-fb08-4821-ba31-77f3b3f478d2', 'thinking-tool-causal', 'Thinking tool: Causal Mapping', 'vertical_horizontal', 'Boxes are stored values, data, steps or settings. Arrows are of three kinds: data flow (this output is that input), state update (this step changes that stored value) and feedback (an output returns as an input). Marks show delays and which loops reinforce or balance. People appear as separate boxes for design and use decisions. Points of change are rules or settings a designer can alter. No box holds a goal or belief of the machine.', 'Causal Mapping in Computational-Core. Role in this space: primary. Stored values, data flow and feedback are what the space uses to explain what systems do, and arrows can carry exactly those three relations. The tool fits every stage from tracing a program to reading a training loop. It leads at 6-8 and shares the lead at 3-5. Form: Boxes are stored values, data, steps or settings. Arrows are of three kinds: data flow (this output is that input), state update (this step changes that stored value) and feedback (an output returns as an input). Marks show delays and which loops reinforce or balance. People appear as separate boxes for design and use decisions. Points of change are rules or settings a designer can alter. No box holds a goal or belief of the machine. What it must not bring in: No machine goals, beliefs or understanding as boxes. No arrows labelled wants or tries. No organism loops such as homeostasis or population growth. Where a person decides, draw the person as a separate box with an arrow to the rule they set.', 'Which arrow carries data, which one changes a stored value, and where does an output come back as an input?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Gopnik et al. (2004); Schulz and Gopnik (2004); Danish (2014); Keil (2006); Levy and Mioduser (2008); Swidan et al. (2018); Pea (1986); Sorva (2013); Kuhn (2007); Grotzer and Basca (2003); Ben-Zvi Assaraf and Orion (2010); Dickes et al. (2016); Evagorou et al. (2009); Lehrer and Schauble (2012); Qian and Lehman (2018); Sweeney and Sterman (2007); Ben-Zvi Assaraf and Orion (2005); Chi et al. (2012); Resnick (1996); Sweeney and Sterman (2000); Rahwan et al. (2019); Brinkmann et al. (2023). MethodsBase record: OE-METHOD-causal-mapping. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["Loops and arrows between factors are untested at K-2, so the K-2 station is a single chain.","Most evidence on maps with loops comes from middle school and adults, and the 9-12 stations rest on it.","The project''s own causal-mapping paper was not read in full for this draft.","No source tests whether students can trace a fault back along the arrows of a map. The 6-8 function-box station rests on studies of programming difficulty."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('4bd55983-ade4-5138-a8aa-55e5542412eb', 'b1e529a5-f584-5647-8858-db2871318297', '04edbe9b-292d-5101-a009-fc46ead81427', 1, 'K-2, Machines Follow Rules People Write (precursor). Children build a picture-card chain for a toy that plays a song when its button is pressed: person writes rule, button pressed, rule runs, song plays. They remove or swap the rule card and show which later cards stop. Every arrow means ''makes happen''. Example: A toy that plays a song when its button is pressed. Shown as: Picture cards in one row joined by a single kind of arrow. New demand: First causal chain. The person who wrote the rule is the first card. Concepts: Program, Algorithm.', 'd5b9a8e1-3f8d-5100-9a23-b4d0aae498f9', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('fe025fe7-e8f5-5446-9a96-324ec47afcf4', 'b1e529a5-f584-5647-8858-db2871318297', '8c7bc083-021f-5891-b502-de2f708a1e09', 2, '3-5, Sequences, Loops and Conditions (full). Students trace a short program with a loop and a condition. They draw a box for each stored value and each step that changes it, with arrows for ''changes'' and ''is read by''. They write the value in each box after every pass and mark where a fault first changes a value. Example: A loop that counts up to ten and stops one pass early. Shown as: Boxes and arrows on paper, with a column of values for each pass of the loop. New demand: Adds change over time: the same box holds a new value after every pass, and one value feeds into itself. Concepts: State, Program, Algorithm.', 'cf5195de-3352-52d0-8e04-b7fc14ede8de', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('1a402938-d1cd-5fcc-be47-6736327cbec1', 'b1e529a5-f584-5647-8858-db2871318297', '71bc5265-fbcd-5e5a-b093-399a24bce44d', 3, '3-5, Models and Simulations of Everyday Systems (full). Students build a model of a traffic light with named parts: timer, light colour and count of cars waiting. They draw arrows for what changes what at each tick, run the simulation by hand with counters, record the cars waiting after each tick, and mark one thing the model leaves out. Example: A traffic-light model with a timer, a light colour and a count of waiting cars. Shown as: Parts as cards on a table, arrows as string, tick counts in a table. New demand: Adds several connected parts and time steps, so one cause can act on more than one box. Concepts: Model, Simulation, State.', 'ea8aba67-5ef6-59cd-9f1f-6198c3966353', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('71cab180-77e9-5673-92bd-9337238f675c', 'b1e529a5-f584-5647-8858-db2871318297', 'f63a89a8-8a27-5cd6-acdf-7ed9f179442b', 4, '6-8, Encoding Text, Images and Numbers (full). Students map a message sent in binary. Boxes: text, scheme, bits, receiver''s scheme, decoded text. Arrows show data flow. They change the receiver''s scheme card and mark which later boxes change, then explain why a decoder needs the scheme. A second map shows a smaller encoding that drops detail. Example: A short text message encoded and decoded with two different character tables. Shown as: Boxes with data-flow arrows. The scheme is a box with its own arrow. New demand: A setting, the scheme, is a cause with its own arrow, and a mismatch shows up several boxes later. Concepts: Representation, Data, Specification.', '6fe408fb-82b8-5eb7-84a5-eecf93c7946f', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('be17bb64-1206-587e-a194-f54d4784605f', 'b1e529a5-f584-5647-8858-db2871318297', '45c484c9-e753-5bb3-86af-086bc28fce31', 5, '6-8, Agent-Based and Feedback Models (full). Students map a traffic model in which each car slows when the car ahead is close. They find a reinforcing loop (more cars in a stretch slow the stretch, so more cars pile in) and a balancing loop (a car that slows lets its gap grow, so it can speed up). They mark the delay, change one rule, rerun and name the arrow they changed. Example: A traffic model in which each car slows for the car ahead. Shown as: Boxes and arrows on a whiteboard, with plus and minus signs and a delay mark. New demand: Adds loops: an output returns as an input after a delay. Students find the cause in the shared rule, with no controlling car. Concepts: Feedback, Model, Distributed System, Simulation.', '7024c45a-e091-5f8f-b41c-c70e70cb69c3', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('bd2335e8-e404-5793-9bd9-2e7cf8c5a636', 'b1e529a5-f584-5647-8858-db2871318297', '31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', 6, '6-8, Decomposition, Functions and Testing (full). Students split a problem into three functions and draw each function as a box, with arrows for the values passed in and out. They run a failing test case and mark the arrow where a value first goes wrong, then name the function to fix. Example: A report program split into read the scores, add them up and print the result. Shown as: Boxes for functions, arrows for passed values, a red mark on the first wrong value. New demand: Reads the map to decide where to look. A fault shows up downstream of its cause, so students trace back along arrows. Concepts: Decomposition, Abstraction, Specification, Program.', 'a3af1799-c882-5b7e-88d6-da912fbc59f6', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('09cfbe65-831a-59c0-9776-d6ecf5ffcc22', 'b1e529a5-f584-5647-8858-db2871318297', 'e6374470-9533-570e-8d98-0e5b24060f4d', 7, '9-12, Machine Learning, Search and Distributed Systems Compared (extended). Students map a recommender that is retrained on click data. Boxes: ranking rule, items shown, clicks, training data, next version. They add boxes for the people who set the objective and the people who click. They find the loop through people, label its delay, and name two points where a designer could change the loop. Example: A video recommender that is retrained each week on what people clicked. Shown as: Boxes and arrows, person boxes in a separate colour, delay marks on arrows. New demand: Adds a loop that runs through people with a weekly delay, and a point of change chosen together with its side effects. Concepts: Machine Learning, Feedback, Data, Model.', '63046d12-d8d7-5830-b2df-ac2833e913f0', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('4dc817c1-6f67-50b4-b22f-547e1d392636', 'b1e529a5-f584-5647-8858-db2871318297', '22e68923-d1f7-54a7-9cb5-6a3591c04a02', 8, '9-12, Information, Compression and the Limits of Representation (extended). Students map what happens when a program adds 0.1 ten thousand times. Boxes: stored precision, rounding at each step, running total, final result. They mark the delay before the error shows, see that it builds as the total grows, and name the limit of the representation. Example: A running total of 0.1 added ten thousand times drifts away from 1000. Shown as: Boxes for each quantity, with the running total drawn as a tank that fills. New demand: Reads an accumulating quantity: small errors build over many steps and show late. Concepts: Representation, State.', '6fe408fb-82b8-5eb7-84a5-eecf93c7946f', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('d588d665-5f26-57ee-bbc1-9de19df4da1b', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '3eceaf9b-fb08-4821-ba31-77f3b3f478d2', 'thinking-tool-payoff', 'Thinking tool: Payoff Matrices', 'vertical_horizontal', 'A table with one row for each option of system A and one column for each option of system B. Options are rules or learned policies. K-2 uses outcome cards with no scores. 3-5 adds scores that a designer set for both. From 6-8 a dilemma appears: the rule that scores best for each program alone gives both a lower score than another pair. The way out is a changed rule, objective or data.', 'Payoff Matrices in Computational-Core. Role in this space: limited. A payoff here is a score that a designer sets, and a program has no wants. The tool fits only where two rules meet, such as devices sharing a link or competing pricing programs. It appears in a reduced form at K-2 and 3-5 and in full from 6-8. Form: A table with one row for each option of system A and one column for each option of system B. Options are rules or learned policies. K-2 uses outcome cards with no scores. 3-5 adds scores that a designer set for both. From 6-8 a dilemma appears: the rule that scores best for each program alone gives both a lower score than another pair. The way out is a changed rule, objective or data. What it must not bring in: No machine that wants, trusts, fears or feels fairness. No promises or messages between programs as a way out. No fitness or stable-strategy ideas. A different outcome comes from a changed rule, objective or data, and a person makes that change.', 'If both programs follow their own rule, which cell do we land in, and who set the scores in that cell?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Levy and Mioduser (2008); Harbaugh et al. (2001); Sutter et al. (2019); Steinbeis et al. (2012); Swidan et al. (2018); Steinberg et al. (2009); Rahwan et al. (2019); Hedden and Zhang (2002). MethodsBase record: OE-METHOD-payoff-matrices. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["No study found tests whether students can spot a dilemma from a payoff table. The nearest evidence is on fairness choices, rational choice and delay discounting.","No study found tests two-party outcome tables with children aged 5 to 8. The nearest evidence is on fairness choices at ages 3 to 8 and on kindergartners'' explanations of robot rules.","Game studies with children come from a few societies, so results from one classroom may differ."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('2e88a89e-93ae-5c55-ba6a-9d52ec1c5725', 'd588d665-5f26-57ee-bbc1-9de19df4da1b', '04edbe9b-292d-5101-a009-fc46ead81427', 1, 'K-2, Machines Follow Rules People Write (precursor). Two toy trains approach a one-track bridge, each with a rule card: go first or wait. Children fill a four-cell outcome table for every pair of cards: crash, one crosses, both wait. They pick a pair of cards for a smooth run and say who would change a card to fix a crash. Example: Two toy trains at a one-track bridge, each with a go-first or wait rule card. Shown as: A four-cell table on the floor, filled with picture cards. New demand: First two-party table: each cell is the outcome of one pair of rule cards. No scores yet. Concepts: Program, Algorithm.', 'd5b9a8e1-3f8d-5100-9a23-b4d0aae498f9', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('4f816645-cae4-5869-a938-9d08ced79fa9', 'd588d665-5f26-57ee-bbc1-9de19df4da1b', '8c7bc083-021f-5891-b502-de2f708a1e09', 2, '3-5, Sequences, Loops and Conditions (precursor). Students program two sprites that each take the left or right lane using a condition. The game designer''s score table gives points for each pair of lanes. They fill the table by running all four cases, say which rule pair gives the higher total, then change the designer''s points and rerun. Example: Two game sprites that each take the left or right lane by a rule, with points set by the designer. Shown as: A four-cell table with two scores in each cell, filled from test runs. New demand: Adds scores that a designer set for each party. Students find that changing the score table changes the best pair. Concepts: Program, Algorithm.', 'd5b9a8e1-3f8d-5100-9a23-b4d0aae498f9', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('a7f27b7f-9397-5588-97f2-11f7e4fdeaa2', 'd588d665-5f26-57ee-bbc1-9de19df4da1b', '45c484c9-e753-5bb3-86af-086bc28fce31', 3, '6-8, Agent-Based and Feedback Models (full). Students simulate two devices that share one link, each sending at full or half rate. A score counts messages delivered. They fill the matrix, find the cell where both send full and many messages are dropped, and compare one round with a hundred rounds. They test a rule that halves the rate after a drop. Example: Two computers sharing one network link, each sending at full or half rate. Shown as: A two-by-two table with both scores, plus a graph of delivered messages by round. New demand: Adds a dilemma and a comparison of one round with a hundred rounds. It appears only if the link is set so that both sending full delivers fewer messages than both sending half. Concepts: Distributed System, Feedback, Model, Simulation.', '4663fd6b-bad8-5bc8-972c-b1f24cf0dd4d', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('43849c3c-e68a-55db-b48c-4c37a9a1c8fe', 'd588d665-5f26-57ee-bbc1-9de19df4da1b', 'e6374470-9533-570e-8d98-0e5b24060f4d', 4, '9-12, Machine Learning, Search and Distributed Systems Compared (extended). Students set up two pricing programs that each hold the price or undercut by one percent. The designer''s score is profit. They fill the matrix, search it for each program''s best response, and run repeated rounds with a learned rule that adjusts from the score. They then change the objective, for example by adding a price floor, and see the cells change. Example: Two online shops with pricing programs that hold or undercut. Shown as: A two-by-two table of profit scores, plus a plot of prices over rounds. New demand: Adds a learned policy and a choice of objective. Changing the objective changes the outcome. Concepts: Search, Machine Learning, Specification, Feedback.', '244aa554-5721-559e-be7e-4e3d4331e644', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('d00da219-05b6-59bc-9ad5-7ccde1e89cb6', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '3eceaf9b-fb08-4821-ba31-77f3b3f478d2', 'thinking-tool-analogy', 'Thinking tool: Analogy Mapping', 'vertical_horizontal', 'Two or three systems or problems side by side. Rows are shared procedure: inputs, steps, stored values, rules, feedback and who set the objective. A last column, where it breaks, is filled for every row. A model may be mapped to the system it models, and two encodings or two methods may be mapped to each other. People, animals and organism lineages are not partners in a map.', 'Analogy Mapping in Computational-Core. Role in this space: primary. Comparing systems and problems on shared procedure is how the space''s concepts transfer: from recipe to program, model to case, one method to another. The break column keeps machine and person apart. It leads at K-2 and shares the lead at 9-12. Form: Two or three systems or problems side by side. Rows are shared procedure: inputs, steps, stored values, rules, feedback and who set the objective. A last column, where it breaks, is filled for every row. A model may be mapped to the system it models, and two encodings or two methods may be mapped to each other. People, animals and organism lineages are not partners in a map. What it must not bring in: No human or animal mind as a partner in the map. No learning described as understanding. No organism lineage. The break column says that a machine has no wants and that a designer chose its objective.', 'Which row matches in both cases, and what is the first thing that stops matching when you test the comparison?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Goswami and Brown (1990); Kotovsky and Gentner (1996); Loewenstein and Gentner (2005); Richland et al. (2006); Levy and Mioduser (2008); Bernstein and Crowley (2008); Gentner and Toupin (1986); Schwarz et al. (2009); Coll et al. (2005); Grosslight et al. (1991); Alfieri et al. (2013); Spiro et al. (1989); Gick and Holyoak (1983); Rahwan et al. (2019); Richland and Simms (2015). MethodsBase record: OE-METHOD-analogy-mapping. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["Naming where an analogy breaks is untested with school students at K-2 and 3-5.","Look-alike features pull attention away from matching roles at every age studied, so the row cards at K-2 and 3-5 need to be tested for this.","Seventh and eleventh graders mostly treat a model as a copy, so the 6-8 and 9-12 break columns carry the weight and need classroom testing."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('64452e16-6cb8-5b75-b347-f4a72987625c', 'd00da219-05b6-59bc-9ad5-7ccde1e89cb6', 'bd2869a3-e2d1-58c1-9878-0c17f2a21c68', 1, 'K-2, Following and Writing Steps (precursor). Children lay a recipe card beside the arrow cards that steer a floor robot. They match step to step with string, then say what each list does if one step is missing or swapped. They finish the sentence: these lists are alike because order matters, and they differ because... Example: A recipe card for a sandwich beside arrow cards that steer a floor robot. Shown as: Two columns of picture cards joined by string, with a third column for differences. New demand: First break column: name one way two step lists differ, such as a vague step (a pinch) and an exact one (forward 2). Concepts: Algorithm, Program.', '91071763-b749-515d-a80e-f1f6d1eaf0fa', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('a0c86914-0a25-5282-9823-7d7eeb0d6891', 'd00da219-05b6-59bc-9ad5-7ccde1e89cb6', '04edbe9b-292d-5101-a009-fc46ead81427', 2, 'K-2, Machines Follow Rules People Write (precursor). Children compare a vending machine with a pedestrian traffic light. For each, they say what it takes in, what rule it follows, what it does and who wrote the rule. They find one thing both share and one thing that differs, and say who would fix a wrong rule. Example: A snack vending machine beside a pedestrian traffic light. Shown as: Two picture columns with four row cards and a difference card at the bottom. New demand: Matches by what each part does and ignores look-alike parts, such as both having buttons. Concepts: Program, Algorithm.', 'd5b9a8e1-3f8d-5100-9a23-b4d0aae498f9', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('0e622371-a958-51bd-a667-b029f014e4b0', 'd00da219-05b6-59bc-9ad5-7ccde1e89cb6', '71bc5265-fbcd-5e5a-b093-399a24bce44d', 3, '3-5, Models and Simulations of Everyday Systems (full). Students set a lunch-line simulation, with counters moving through three steps, beside the lunch line itself. They match parts row by row: arrivals, waiting, serving. In a last column they write what the model leaves out and one change to the model that would add it. Example: A counter-and-card simulation of the lunch line beside the lunch line itself. Shown as: A three-column table: part of the line, part of the model, what the model leaves out. New demand: Maps a model to its case and fills the break column with what the model leaves out, plus one change that would add it. Concepts: Model, Simulation, Abstraction.', 'ea8aba67-5ef6-59cd-9f1f-6198c3966353', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('46c856a3-ee64-5f26-8481-04293f067cc0', 'd00da219-05b6-59bc-9ad5-7ccde1e89cb6', 'f63a89a8-8a27-5cd6-acdf-7ed9f179442b', 4, '6-8, Encoding Text, Images and Numbers (full). Students encode one small drawing as an 8 by 8 grid and as a 4 by 4 grid. They map the two row by row on size in bits, detail kept and what a decoder must know. They flip one bit in each grid and compare the damage. The break column names the detail the smaller grid cannot return. Example: One drawing stored as an 8 by 8 grid of pixels and as a 4 by 4 grid. Shown as: Two pixel grids and a table of bits, size and detail kept. New demand: Maps two stored forms of the same data, states what each loses, and tests the map: one wrong bit damages a larger share of the small grid. Concepts: Representation, Data, Information.', '6fe408fb-82b8-5eb7-84a5-eecf93c7946f', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('cc4ba1b4-7272-56c1-91bd-511541ea3f2d', 'd00da219-05b6-59bc-9ad5-7ccde1e89cb6', '45c484c9-e753-5bb3-86af-086bc28fce31', 5, '6-8, Agent-Based and Feedback Models (full). Students map a classroom thermostat simulation to the heating it models: the temperature value, the on or off rule, the heater and the delay. They test the map by changing the room in the simulation and finding the row that stops matching. The break column records where the simulation gives exact numbers and the room does not. Example: A thermostat simulation beside the heating system of their classroom. Shown as: A two-column table with parts as rows, plus a break column. New demand: Tests the map by changing the model and finds the row that fails. A model is a built description of the room, and students list where it differs from the room. Concepts: Model, Simulation, Feedback.', 'ea8aba67-5ef6-59cd-9f1f-6198c3966353', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('4be2f9ec-57d7-5665-8e35-b856d5dfc4cd', 'd00da219-05b6-59bc-9ad5-7ccde1e89cb6', 'e6374470-9533-570e-8d98-0e5b24060f4d', 6, '9-12, Machine Learning, Search and Distributed Systems Compared (extended). Students build a three-way map of a spam filter (machine learning), a route finder (search) and a file-sharing network (distributed system). Rows: input, what changes, what it guarantees, who set the objective. For each pair of columns they write where the comparison breaks and what the system can be said to do without intention. Example: A spam filter, a route finder and a file-sharing network. Shown as: A three-column table with four rows and a break cell for each pair. New demand: Maps three cases at once and states what each guarantees. Each break cell is written without intention words. Concepts: Machine Learning, Search, Distributed System, Model.', '63046d12-d8d7-5830-b2df-ac2833e913f0', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('2b856c06-8550-534c-ae6f-c9125a0d2920', 'd00da219-05b6-59bc-9ad5-7ccde1e89cb6', '06ca57c6-f90e-5354-84b4-ee88dd292147', 7, '9-12, Correctness and Efficiency (full). Students map linear search and binary search for a name in a sorted list. Rows: input needed, steps for 10, 1,000 and 1,000,000 names, and what each guarantees. In the break column they state the input condition under which binary search gives a wrong answer, and justify a choice for a stated need. Example: Linear search and binary search for a name in a sorted list. Shown as: A two-column table with step counts in the rows and a break column. New demand: Compares by how steps grow with input size, and names the input condition that breaks one method. Concepts: Algorithm, Specification, Abstraction.', '91071763-b749-515d-a80e-f1f6d1eaf0fa', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

UPDATE projects SET introduction = introduction || '

Thinking tools. Four OpenEvo thinking tools (Tinbergen''s Questions, Causal Mapping, Payoff Matrices and Analogy Mapping) are deployed across the grade bands of this space as four threads named "Thinking tool: ...". Computational-Core explains what systems do through data, rules, state, models and feedback, and gives machines no wants or understanding. The four tools serve that aim as ways to trace and compare procedures. Causal Mapping follows values and signals. Analogy Mapping compares systems on shared procedure. Tinbergen''s Questions sort answers about one system. Payoff Matrices score pairs of rules against a designer''s objective. Most break columns and questions lead back to the people who chose the rules. K-2: Analogy Mapping leads, matching step lists and simple machines, with a fixed row for who wrote the rule. 3-5: Causal Mapping leads, tracing stored values and the parts of a simulation. 6-8: Causal Mapping adds feedback loops, and Analogy Mapping checks a model against its case. 9-12: Analogy Mapping compares methods, and Tinbergen''s Questions trace one system''s mechanism, development, function and version history. Payoff Matrices start as outcome tables, compare joint totals in 3-5 and read each party''s score in 6-8. The threads have the status proposed. AI drafted them and no subject expert has reviewed them.' WHERE id = 'bac697ab-febe-5111-a5bd-f266b8b2d837' AND introduction NOT LIKE '%Thinking tools. Four OpenEvo thinking tools%';

