INSERT INTO literature_references (project_id, literaturebase_id, title, authors, year, doi, venue, type, status, notes, tags)
SELECT 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'OE-LITERATURE-resnick-1996', 'Beyond the Centralized Mindset', '["Resnick, Mitchel"]'::jsonb, 1996, '10.1207/S15327809JLS0501_1', 'Journal of the Learning Sciences', 'article', 'draft', 'Evidence for the thinking-tool threads of Computational-Core (AI-drafted 2026-10-26, no expert review). People often assume centralized control where none exists, as seen in high-school students'' StarLogo projects.', ARRAY['thinking-tools', 'proposed-link']::text[]
