SELECT 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'OE-LITERATURE-gick-holyoak-1983', 'Schema induction and analogical transfer', '["Gick, Mary L.","Holyoak, Keith J."]'::jsonb, 1983, '10.1016/0010-0285(83)90002-6', 'Cognitive Psychology', 'article', 'draft', 'Evidence for the thinking-tool threads of Computational-Core (AI-drafted 2026-10-26, no expert review). Classic adult study of how comparing analogous cases builds a schema that supports transfer; the abstract was not retrieved.', ARRAY['thinking-tools', 'proposed-link']::text[]
WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = 'bac697ab-febe-5111-a5bd-f266b8b2d837' AND literaturebase_id = 'OE-LITERATURE-gick-holyoak-1983');

-- Interdisciplinary
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('8d71b081-ce78-53bf-8ac4-8aa547dbfe61', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'thinking-tool-tinbergen', 'Thinking tool: Tinbergen''s Questions', 'vertical_horizontal', 'The full expanded grid across domains: mechanism, development, evolutionary history, cultural history and family history, each with inside and outside causes, plus the function question. Rows are renamed for each domain; for machines they become inputs and rules, training and updates, and the lineage of versions. Rows that do not apply are marked empty with a reason. Younger bands use two or three rows.', 'Tinbergen''s Questions in Interdisciplinary. Role in this space: primary. The grid is the main way Interdisciplinary asks one question of an animal, a person and a machine, and it shows which rows change meaning. It leads at 9-12 and shares the lead with Causal at 6-8, where students have enough sense of time and cause to use it. Younger bands get a reduced form. Form: The full expanded grid across domains: mechanism, development, evolutionary history, cultural history and family history, each with inside and outside causes, plus the function question. Rows are renamed for each domain; for machines they become inputs and rules, training and updates, and the lineage of versions. Rows that do not apply are marked empty with a reason. Younger bands use two or three rows. What it must not bring in: No station calls a language model or an app a species with offspring, and no machine gets wants or a family. The Guide''s wording appears only inside the analogy tool, with a breakdown column. Near and far causes are never ranked by importance, and how-versus-why is not taught as the grid''s meaning.', 'Which row is this answer in: what is happening now, how it grew, how it was passed on, or what it does for them? Does that row mean the same thing for an animal, a person and a machine?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Kelemen et al. (2014); Barton and Levstik (1996); Gelman and Wellman (1991); Kelemen (1999); Dewsbury (1992); Kuhn (2007); Brown et al. (2020); Lehrer and Schauble (2012); Shtulman et al. (2016); Gregory (2009); Laland et al. (2011); Lira et al. (2024); Kelemen and Rosset (2009); Rahwan et al. (2019); Brinkmann et al. (2023); Shtulman and Valcarcel (2012); Barnes et al. (2017); Nehm and Reilly (2007). MethodsBase record: OE-METHOD-tinbergens-questions. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["No study found teaches the full grid to children under 11. The K-2 and 3-5 stations rest on studies of component skills such as sorting by time and learning selection from storybooks.","Rahwan et al. ground the four classic questions at three scales. Brinkmann et al. ground variation, transmission and selection in machine culture and never mention Tinbergen. The cultural-history and family-history rows rest on the deck and the human-behaviour literature.","Tinbergen, Dewsbury, Laland and Bateson were known only through the deck''s quotations and Rahwan''s citations. Ariew and Panchanathan, the source for adding agency, were not read and no station cites them. Evidence from school students on the agency, cultural-history and family-history rows is thin."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('f0e1daa8-4b52-5939-ac32-cef75195f0b8', '8d71b081-ce78-53bf-8ac4-8aa547dbfe61', '04d57493-ac2f-5ec6-a1ba-0596eae3158a', 1, 'K-2, Things That Get Passed On (precursor). Children place picture cards for a family trait and a family recipe on a three-part strip: now, when I was little, long ago in the family. For each card they answer: what is happening now, and where did it come from? They sort each card into ''came with me'' or ''someone showed me'', and spot how two cousins'' soups differ. An adult writes the answers. Example: Curly hair that runs in a family, and a grandmother''s soup recipe that two cousins both cook. Shown as: Picture cards on a strip: now, when I was little, long ago. New demand: First sorting of causes by when they happened. The function question stays out, because young children give purpose answers for traits. Concepts: Inheritance, Variation, Transmission. Domains: biology, culture.', '71010850-ffce-5968-b6a5-38c0b8599620', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('8f14ee82-7ed9-5528-8034-52058656d39d', '8d71b081-ce78-53bf-8ac4-8aa547dbfe61', '31b2be29-7a8c-5f98-a447-55ecf57f1ff9', 2, '3-5, Comparing How Different Living Things Act, Learn, and Teach (precursor). Students watch a clip of a young animal learning from an adult and ask three questions: what set it off just now, how did it get here (practice, watching, whatever help it got), and where did the habit come from (the group''s way over many years). They repeat the questions for a child learning a skill and name one difference between the helpers. Example: A young chimpanzee learning to crack nuts by watching its mother, and a child learning to tie shoelaces. Shown as: Three-row chart with picture clues and one sticky note per cause. New demand: Keep a trigger now apart from a cause during growing up and a cause over many years, with one sticky note per cause. Concepts: Learning, Teaching, Development, Scaffolding. Domains: biology, cognition, education.', '241ac4b1-00b3-517c-b3b5-10029f1efdc6', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('28b7e5b4-4e45-5f2f-8e2f-a6013049c286', '8d71b081-ce78-53bf-8ac4-8aa547dbfe61', 'a1bc92d8-3730-53b8-a059-f3999e4387cf', 3, '3-5, Comparing Communities and Changing Tools Over Time (precursor). Students order picture cards of a writing tool on a timeline and say what each version kept from the one before and what changed. They then ask what outcome the tool creates for people today and why people still use it. The teacher records any answer that gives the tool a purpose of its own. Example: Writing tools over centuries: charcoal, quill, pencil, ballpoint pen. Shown as: Timeline of picture cards with a ''kept'' note and a ''changed'' note under each. New demand: Add a cultural-history row: causes that reach back decades to centuries, with dates put in order on a timeline. Concepts: Technology, Innovation, Culture, Descent. Domains: technology, culture, education.', '1d89ba05-d574-53ea-aaa9-c513d9125e96', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('50dd693d-a2f8-5444-ae1b-c9b060cc7286', '8d71b081-ce78-53bf-8ac4-8aa547dbfe61', '6315aad7-35b7-52dc-9dd2-1b82d707a768', 4, '6-8, The General Pattern: Variation, Selection, Transmission (full). Students ask the history and function questions of two traits side by side. They write biological history and cultural history as separate rows, then answer why does it exist today for each trait, saying what was kept and who or what did the keeping. They also ask whether chance could explain why a trait persists. Example: Beak shape in a finch population, and a swipe feature kept across versions of a phone app. Shown as: Two-column grid with rows from mechanism to function and inside and outside boxes. New demand: Keep the biological and cultural history rows apart, mark the row that stays empty for each trait and say why, and answer the function question separately. Concepts: Evolutionary Process, Selection, Fitness, Drift. Domains: biology, culture, technology.', '212e3ab0-5575-572b-89fe-cff0ab90594d', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('6b5a2d09-5a78-5872-b7e2-fb910ac9935d', '8d71b081-ce78-53bf-8ac4-8aa547dbfe61', '3a112595-4435-5db0-950d-ca7c6da5160d', 5, '6-8, Agency, Niche Construction, and Selection (full). Students fill the grid for earthworms that loosen soil, once for the soil change and once for a later worm that is well suited to it. They split each row into inside causes (body, growth) and outside causes (soil, weather, other worms). They test each why answer: does it say what a worm meant to do, or what happened across generations? Example: Earthworms mixing and loosening soil so that later worms and plants do better. Shown as: Grid with inside and outside boxes and an arrow from the outside box to later generations. New demand: Split rows into inside and outside causes, and see that an organism''s action can become an outside cause for later generations. Concepts: Niche Construction, Agency, Adaptation, Selection Pressure. Domains: biology.', '3756d347-25a4-5484-bac4-2a3a061f6def', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('f0ac26d3-bdd2-5eca-a5a6-9d25680dc2a8', '8d71b081-ce78-53bf-8ac4-8aa547dbfe61', '5d938d91-e81b-516c-ba58-a234b6d5559f', 6, '9-12, Agency and Niche Construction Across Biological and Technological Systems (extended). Students ask the same questions of three cases in one three-column grid. For the algorithm they rename the rows: inputs and rules, training data and updates, lineage of versions, and what builders and users gain. They mark rows that stay empty and write why. The machine column follows Rahwan et al.''s four classic questions. Example: Bird song, a student''s habit of checking a feed, and a video recommendation algorithm. Shown as: Three-column grid with renamed rows and empty cells marked with a reason. New demand: Say, row by row, where a question stops meaning the same thing for animals, people and machines. Concepts: Agency, Information, Communication, Feedback. Domains: biology, cognition, culture, AI and computation.', '993c989a-79d2-5262-b20f-9636504623cd', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('bc8e4cb2-53cc-52c4-baaf-a7aac4ae1623', '8d71b081-ce78-53bf-8ac4-8aa547dbfe61', 'e820dc2d-9317-57d1-8475-22a701fc486a', 7, '9-12, Collective Intelligence, Distributed Cognition, and Coevolving Technology (extended). Students take one social media platform and ask the cultural-history and function questions. How did its features get kept across versions, who chooses what spreads, and what does it do for users and for builders? They then draw the loop from what users do back to what the next version shows. This follows Brinkmann et al. on variation, transmission and selection. Example: The ranking feature of a short-video app across five years of versions. Shown as: Row grid plus a looped arrow from ''what users do'' to ''next version''. New demand: Add the loop from consequences back to what gets kept, with a human decision at every turn. Concepts: Culture, Selection, Diffusion, Feedback. Domains: culture, technology, AI and computation.', '8c0525a4-0873-52c6-a097-8915714a33ae', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('ac7df313-3506-5264-9448-c11ddc6d0f0b', '8d71b081-ce78-53bf-8ac4-8aa547dbfe61', 'ba60a3be-0135-5b53-b88f-a7aecfe0ed96', 8, '9-12, The Shared Structure of Discovery: Darwin''s Notebooks and the History of Science (extended). Students turn the grid on a habit of thought: explaining a trait by need. They ask what triggers the habit under time pressure, how it develops in childhood, how everyday language keeps it, and what it does for the thinker. They then rewrite one explanation using variation and selection. Example: The sentence ''giraffes grew long necks because they needed to reach leaves''. The cause of long necks is debated, so the rewrite is one hypothesis. Shown as: Five-row grid applied to one sentence, with the rewritten sentence beside it. New demand: Use the grid on one''s own thinking, and judge each answer by its row so that a function answer stops standing in for a mechanism answer. Concepts: Intuitive Theories, Metacognition, Adaptation, Variation. Domains: cognition, education, biology.', 'ce917c30-aaf6-59a9-b20a-36ecebf5b68f', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('26e5958a-cd92-5e86-9cde-35b5d860a08a', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'thinking-tool-causal', 'Thinking tool: Causal Mapping', 'vertical_horizontal', 'Factors joined by arrows with plus and minus signs, loops, delays and named archetypes. A factor may be a count, a behaviour, a rule, a design or a stored value, and each map labels which kind each factor is. An arrow keeps one meaning per map; where the meaning changes between domains, the map marks the arrow. Points where people could act are named for human systems only.', 'Causal Mapping in Interdisciplinary. Role in this space: supporting. Causal maps carry the loop and delay ideas that Feedback, Niche Construction and Selection Pressure need. At 9-12 the feed map marks which arrows people decide, a program computes or nobody designed. A grid answer or an analogy often becomes an arrow. Evidence for loops under age 11 is thin. Form: Factors joined by arrows with plus and minus signs, loops, delays and named archetypes. A factor may be a count, a behaviour, a rule, a design or a stored value, and each map labels which kind each factor is. An arrow keeps one meaning per map; where the meaning changes between domains, the map marks the arrow. Points where people could act are named for human systems only. What it must not bring in: No arrow gives a population, a gene or a program a goal, and no loop is read as foresight. Arrows that change meaning between domains (an animal''s response, a person''s reason, a designer''s setting) are marked and never merged. Explanations of group patterns by a hidden controller are challenged.', 'Where does an effect come back to its own cause? Who or what decides that arrow: a person, a rule someone wrote, or nobody?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Gopnik et al. (2004); Schulz and Gopnik (2004); Danish (2014); Keil (2006); Grotzer and Basca (2003); Ben-Zvi Assaraf and Orion (2010); Kuhn (2007); Dickes et al. (2016); Evagorou et al. (2009); Sweeney and Sterman (2007); Sweeney and Sterman (2000); Ben-Zvi Assaraf and Orion (2005); Hmelo-Silver and Pfeffer (2004); Chi et al. (2012); Wilensky and Reisman (2006); Resnick (1996); Hanisch and Eirdosh (2020); Rozenblit and Keil (2002); Brinkmann et al. (2023); Rahwan et al. (2019). MethodsBase record: OE-METHOD-causal-mapping. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["No study found teaches causal maps with loops to children under 11. K-2 rests on studies of causal learning in preschoolers and on a bee unit; 3-5 on a few small classroom studies.","Most evidence on drawing and reading maps with delays comes from middle school and adults, and adults do poorly on stocks, flows and delays. The 9-12 stations are a bet that older students do better with explicit teaching of loop types.","The project''s own causal-mapping paper was not read in full here."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('b308a9d5-8ceb-5920-84d3-c0855b75e1a5', '26e5958a-cd92-5e86-9cde-35b5d860a08a', '6f04ee30-2be3-537b-9d0e-b339d9fed79c', 1, 'K-2, Living Things Act to Meet Their Needs (precursor). Children link picture cards with string to show what a bird needs and what it does: hungry, looks for food, finds food, feeds chicks, chicks grow, chicks look for food too. They say ''this makes that happen'' for each pair. The teacher adds a return arrow only if a child notices that the story comes back to the start. Example: A bird that looks for food, feeds its chicks, and has chicks that look for food in turn. Shown as: Picture cards joined by string and arrows, one cause for each arrow. New demand: First arrows between factors: one cause for one effect, with a return arrow shown only when a child spots it. Concepts: Agency, Development, Representation. Domains: biology.', '993c989a-79d2-5262-b20f-9636504623cd', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('de5b351c-0a0b-5a48-87c7-4e2e633aaf37', '26e5958a-cd92-5e86-9cde-35b5d860a08a', 'a1bc92d8-3730-53b8-a059-f3999e4387cf', 2, '3-5, Comparing Communities and Changing Tools Over Time (full). Students map a shared class resource. They draw arrows from who uses it to how much is left to how people feel, and find one cycle: less paint, more grabbing, even less paint. Each arrow gets a plus or minus. They compare a map for a class with a turn-taking rule that others expect and uphold with a map for a class without one. Example: A paint set shared by two table groups, with taking turns or grabbing. Shown as: Factor cards with plus and minus arrows on a table-size poster. New demand: Close one loop: an effect that returns to its own cause, with one sign on each arrow. Concepts: Cooperation, Conflict, Group, Norms. Domains: culture.', 'c13c4fe4-a865-52b5-9203-154e5934dd92', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('40983130-e75b-5b1e-b3bb-77cfb16c9dab', '26e5958a-cd92-5e86-9cde-35b5d860a08a', '31b2be29-7a8c-5f98-a447-55ecf57f1ff9', 3, '3-5, Comparing How Different Living Things Act, Learn, and Teach (full). Students map a learner and a helper. Skill rises with practice, help falls as skill rises, and a slip in skill brings help back. They act it out with a paper bicycle, then draw the same shape for a meerkat pup and an adult who hands over prey in easier and harder forms. They say which helper acts on purpose. Example: A child learning to ride a bicycle while a helper lets go a little at a time. Shown as: Moving cards on a poster; arrows marked plus or minus. New demand: Read a balancing loop: help falls as skill rises. Students check the sign on each arrow aloud. Concepts: Scaffolding, Role, Teaching, Feedback. Domains: education, cognition, biology.', 'e09d4837-14bf-5d3f-839f-f708e982b216', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('67b06394-4f8e-5dcc-83af-b765e8b7e81a', '26e5958a-cd92-5e86-9cde-35b5d860a08a', 'd2dc3119-7af8-55d8-8bfe-b63a4ec56acb', 4, '6-8, How Minds and Cultures Search for Better Ideas (full). Students map how a class library of solved examples speeds up later problems. Each solved problem adds an example, a new problem starts from the closest solved example, and faster work adds more examples. They mark the delay, because the library helps later problems and leaves the present one alone, and predict how the curve bends. Example: A class worked-example library that grows as each problem is solved. Shown as: Factor cards with plus arrows, a loop and a delay mark. New demand: Add a delay: the effect arrives later than the cause. Students mark it and predict how the growth bends. Concepts: Innovation, Search, Knowledge, Analogical Reasoning. Domains: culture, cognition, education.', '183d2755-1489-554c-9b9e-e2cc8792592e', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('78b82c3b-9139-56ed-985c-3b92d8d1cd92', '26e5958a-cd92-5e86-9cde-35b5d860a08a', '3a112595-4435-5db0-950d-ca7c6da5160d', 5, '6-8, Agency, Niche Construction, and Selection (full). Students map how keeping cattle changed human life: herds give milk, milk use raises the advantage of adults who digest it, and such adults may keep more herds (an arrow to test). They mark which arrows act within a lifetime and which act across generations, and give the slow arrows a delay mark. No arrow carries a plan to evolve. Example: Herding families, milk in the diet, and the spread of milk digestion in adults. Shown as: Factor cards with plus arrows, delay marks and two arrow colours: fast and slow. New demand: Separate fast arrows (one lifetime) from slow ones (across generations) and read a loop that has no planner in it. Concepts: Domestication, Niche Construction, Selection Pressure, Feedback. Domains: biology, culture.', '95f07717-21d3-573b-a081-9c8855a489ae', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('d84d1f5c-8454-55ef-ad20-936c1a7eb901', '26e5958a-cd92-5e86-9cde-35b5d860a08a', '6315aad7-35b7-52dc-9dd2-1b82d707a768', 6, '6-8, The General Pattern: Variation, Selection, Transmission (full). Students map how a word for a game spreads and fades. Children hear it, some copy it, copying makes it more common, and when children stop passing it on it ends. A chance arrow (who happens to be copied early) sits beside a reason arrow (a popular older child). They ask which arrow a table of counts could tell apart. Example: A local word for a playground game, spreading through a town and then fading as children stop passing it on. Shown as: Factor cards with a reason arrow and a chance arrow shown in different colours. New demand: Show chance and bias as two separate arrows into one outcome, and say what evidence could tell them apart. Concepts: Diffusion, Drift, Population, Extinction. Domains: culture.', '82f88ea7-c641-579f-a698-5a417581d51c', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('a6b7b5b0-2dfd-5136-b492-a8c86678989e', '26e5958a-cd92-5e86-9cde-35b5d860a08a', 'e820dc2d-9317-57d1-8475-22a701fc486a', 7, '9-12, Collective Intelligence, Distributed Cognition, and Coevolving Technology (extended). Students map how a crowd''s average guess can beat most members: independent guesses go in, averaging comes out, and an arrow from seeing others'' guesses on a shared tally board can break it. They add the copying loop and test it by running a counting game twice, once with private guesses and once with the board in view. No arrow comes from a leader. Example: Guessing the beans in a jar, with and without seeing others'' guesses. Shown as: Factor cards and arrows, with the copying loop drawn in a second colour. New demand: Explain a group result with no controller in the map, and find the arrow that turns a helpful loop into a harmful one. Concepts: Collective Intelligence, Communication, Distributed Cognition, Model. Domains: culture.', '4e4ec762-ee46-53d3-afe3-da41c3d3f6af', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('3933b73f-71c4-5b68-b9d5-ea2e1320f944', '26e5958a-cd92-5e86-9cde-35b5d860a08a', '5d938d91-e81b-516c-ba58-a234b6d5559f', 8, '9-12, Agency and Niche Construction Across Biological and Technological Systems (extended). Students draw the loop between readers, a ranking system and the people who write for it. Clicks become training data, training data changes what is shown, and what is shown changes clicks and what writers make. They add an arrow for a designer''s setting, mark who holds the power to change it, and label each arrow decided, computed or undesigned. Example: A news-ranking feed, its readers and the writers who adjust headlines to it. Shown as: Factor cards, arrows with signs, and three arrow styles: decided, computed, undesigned. New demand: Mark which arrows people decide, which the program computes and which no one designed, and look for an amplifying loop. Concepts: Feedback, Algorithm, Incentive, Power. Domains: AI and computation, culture, technology.', 'b8b2412c-6f27-54f8-b612-4c595d3e9059', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('b4a97bc6-b4f1-5e71-97e1-dd7e756cf1c9', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'thinking-tool-payoff', 'Thinking tool: Payoff Matrices', 'vertical_horizontal', 'A table of outcomes for each pair of choices by two parties. What a payoff is depends on the sense: offspring left by a strategy (biology), costs and benefits as people judge them (culture), a score a designer set (AI and computation). Early bands start with outcome tables and short words. Every table says whose choice it is and whether choice is the right word.', 'Payoff Matrices in Interdisciplinary. Role in this space: limited. Payoff tables fit only the concepts about choices between parties: Cooperation, Conflict, Incentive, Norms, Fitness. Evidence for reading two-party tables under age 11 is thin, so K-2 and 3-5 use outcome tables. The tool earns a place because it shows that a payoff means different things in biology, culture and software. Form: A table of outcomes for each pair of choices by two parties. What a payoff is depends on the sense: offspring left by a strategy (biology), costs and benefits as people judge them (culture), a score a designer set (AI and computation). Early bands start with outcome tables and short words. Every table says whose choice it is and whether choice is the right word. What it must not bring in: No table gives bacteria, bees or programs reasons, trust or fairness. Fitness payoffs are never read as one animal''s choice, and a designer''s reward is never read as what a program wants. Human cases are not used as evidence for what evolved. Calling a human case a game comes with its breakdown column.', 'Who is choosing here, and is choosing the right word? What counts as a good outcome in this table: chicks, something people value, or a score someone set?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Fehr et al. (2008); Blake and McAuliffe (2011); Harbaugh et al. (2001); House et al. (2013); Blake et al. (2015); Sutter et al. (2019); Flobbe et al. (2008); Steinbeis et al. (2012); Steinberg et al. (2009); Hedden and Zhang (2002); Gregory (2009); Shtulman et al. (2016). MethodsBase record: OE-METHOD-payoff-matrices. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["No study found tests whether students can spot a social dilemma from a payoff table. The nearest evidence is on fairness choices, rational choice, delay discounting and strategic play.","The cited studies are adjacent evidence. S49 used college-age players, S44 and S46 covered seven and six societies, and S52 and S53 measured delay and impulse control. None tests reading a payoff table, so the 6-8 and 9-12 moves are bets.","Cooperation results come from a few societies, and costly sharing differs by culture. Results from Saxony classrooms may differ from the cited figures.","The 9-12 three-reading table has no direct study behind it. It rests on the vocabulary''s separate senses of Incentive and Fitness.","Four of six stations are share-or-take dilemmas. A coordination case would widen the range."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('cf92e975-58a7-5534-970b-1adf5db7c8f5', 'b4a97bc6-b4f1-5e71-97e1-dd7e756cf1c9', '8363df74-ecd8-54e9-82f1-e93623f9995c', 1, 'K-2, Ideas That Are Like Other Ideas (precursor). Children act out a two-choice classroom situation: share the blocks or keep them all. They fill a picture table with face cards for what happens to me after each choice, first for one child, then for the pair. Children say what each child wanted, then check whether the table matches. Example: Two children and one box of blocks at choosing time. Shown as: Picture table with face cards, one row per choice. New demand: First outcome table: one choice and its result for me and for the other child. Long-term columns are left out. Concepts: Theory of Mind, Cooperation, Conflict. Domains: cognition, culture.', 'e6f78871-2017-55c6-8739-9a9c3a249315', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('39fca920-e008-5398-b16c-91e627bd1b9d', 'b4a97bc6-b4f1-5e71-97e1-dd7e756cf1c9', 'a1bc92d8-3730-53b8-a059-f3999e4387cf', 2, '3-5, Comparing Communities and Changing Tools Over Time (precursor). Students fill a two-by-two table of words for two classes that share one playground ball in a rainy week. Each class can take the ball every break or take turns. Cells say what happens to each class. A second column asks what happens next week. Results are compared across groups, since classes differ. Example: Two classes and one playground ball in a rainy week. Shown as: Two-by-two table of short sentences with a ''next week'' column. New demand: Two parties with two choices each, and one extra column for later. Evidence for this age is thin, so the teacher watches closely. Concepts: Cooperation, Conflict, Incentive, Group. Domains: culture, education.', 'c13c4fe4-a865-52b5-9203-154e5934dd92', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('f53f4ff0-e7df-5184-955d-1a62e32d4636', 'b4a97bc6-b4f1-5e71-97e1-dd7e756cf1c9', 'ad0173a4-5c64-5d05-96ac-2b61810c4153', 3, '6-8, Culture as Transmitted, Institutions as Stabilizing Structures (full). Students fill a table for two fishers who share a lake: each can take many fish or few, with columns for this season and for ten years on. They find the dilemma, then test two ways out: a norm that members uphold by approval, and a rule with a fine. They name which party holds which kind of power to change the table. Example: Two fishers sharing one lake. Shown as: Two-by-two table with short-term and long-term columns, and a second table after each change. New demand: Find the dilemma in the gap between the short-term and long-term columns, then test two ways out. Evidence for this skill at age 12 is thin. Concepts: Norms, Institutions, Incentive, Power. Domains: culture.', 'c529c772-66e2-5915-93f8-adedafc7732d', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('8e665578-092f-574a-941b-5f014a80fa5e', 'b4a97bc6-b4f1-5e71-97e1-dd7e756cf1c9', '3a112595-4435-5db0-950d-ca7c6da5160d', 4, '6-8, Agency, Niche Construction, and Selection (full). Students fill a payoff table for two bird types that meet at a food patch: one fights, one backs off. Each cell shows the average chicks raised. They read which type leaves more chicks against which, then ask how each type''s share of the population shifts over generations. They state that no bird reads the table. Example: Birds that fight over a food patch and birds that back off. Shown as: Two-by-two table of average chicks, plus a bar for each type''s share over generations. New demand: Read a payoff as offspring left by a type, add a population column, and see that no individual chooses. Concepts: Fitness, Selection, Conflict, Population. Domains: biology.', '2208c511-0a4b-59ad-a8cf-78bde2588a95', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('873cc7b2-6d13-5d69-b293-25895023cc32', 'b4a97bc6-b4f1-5e71-97e1-dd7e756cf1c9', '396e3dd9-4f22-5160-b6c7-3752caefa1b8', 5, '9-12, Selection Across Biology, Culture, Education, and AI (extended). Students fill one dilemma table three times with the same shape: fitness for two inherited strategies, costs and benefits for two neighbours, and a designer''s reward for two programs sharing a server. They compare what choice means in each column and what could change the result: selection over generations, talk and rules, or editing the reward. Example: A shared-resource dilemma read as animal strategies, neighbours'' water use and two programs'' rewards. Shown as: Three copies of one table, with a strip below each: what is a payoff, what is a choice. New demand: Compare three meanings of payoff and choice in one table shape, and say which fix works in each. Concepts: Incentive, Selection, Cooperation, Abstraction. Domains: biology, culture, AI and computation.', 'd74633cc-737d-5760-9c98-28c9381c401f', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('50058178-3cfc-5c72-9442-b4b1330bfca3', 'b4a97bc6-b4f1-5e71-97e1-dd7e756cf1c9', 'ba60a3be-0135-5b53-b88f-a7aecfe0ed96', 6, '9-12, The Shared Structure of Discovery: Darwin''s Notebooks and the History of Science (extended). Students play a repeated two-choice game on a payoff table, first against a classmate and then against a program with a simple stated rule. After each round they write what they expect the other side to do and why, then check the default picture of the other side they started with. They compare how a person and a program revise their play. Example: A repeated two-choice game against a classmate, then against a rule-following program. Shown as: Payoff table plus a round-by-round log: my guess about the other side, what happened. New demand: Reason about the classmate''s picture of you, and state what a rule-following program has in its place. Notice one''s own default assumption about the other side. Concepts: Theory of Mind, Metacognition, Algorithm, Incentive. Domains: cognition, AI and computation.', 'e6f78871-2017-55c6-8739-9a9c3a249315', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('401a0619-398d-5953-a61e-2e2d1bacf61f', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'thinking-tool-analogy', 'Thinking tool: Analogy Mapping', 'vertical_horizontal', 'Two or more cases from different domains side by side, shared relations in rows, and a ''where it breaks'' column filled from the vocabulary''s ''does not carry over'' notes, with the concept named. Selection, Inheritance and Scaffolding have no such note, so a map names the neighbouring note it borrows. A map is a hypothesis that needs separate evidence. K-2 starts with picture cards sorted into same job, looks alike and different.', 'Analogy Mapping in Interdisciplinary. Role in this space: primary. Interdisciplinary exists to carry a concept across domains and to say where it stops. An analogy map with a break column does both, and its break cells are the vocabulary''s own ''does not carry over'' notes. It leads at K-2 and 3-5 with concrete cards, and returns at 9-12 with three or more senses. Form: Two or more cases from different domains side by side, shared relations in rows, and a ''where it breaks'' column filled from the vocabulary''s ''does not carry over'' notes, with the concept named. Selection, Inheritance and Scaffolding have no such note, so a map names the neighbouring note it borrows. A map is a hypothesis that needs separate evidence. K-2 starts with picture cards sorted into same job, looks alike and different. What it must not bring in: No map treats surface resemblance as evidence, and no map ends without a break column. ''Species'' and ''offspring'' for language models appear only as quoted words under test in the one 9-12 map. A machine is never given wants or a family. Each map names the senses it joins.', 'Which rows match because the relations are the same, and which only because the pictures look alike? Where does the map break, and which note says so?', 'AI-drafted on 2026-10-26 from the OpenEvo Teacher''s Guide chapter on thinking tools, the MethodsBase records of the four tools and the verified evidence listed in the thread. No subject-matter expert has reviewed it and no classroom has tested it. Evidence used for the stations: Goswami and Brown (1990); Kotovsky and Gentner (1996); Loewenstein and Gentner (2005); Gentner (1988); Richland et al. (2006); Levy and Mioduser (2008); Mioduser et al. (2009); Bernstein and Crowley (2008); Gentner and Toupin (1986); Alfieri et al. (2013); Hitron et al. (2019); Festerling and Siraj (2020); Grosslight et al. (1991); Schwarz et al. (2009); Coll et al. (2005); Spiro et al. (1989); Gick and Holyoak (1983); Richland and Simms (2015); Gentner (1983); Rahwan et al. (2019); Brinkmann et al. (2023). MethodsBase record: OE-METHOD-analogy-mapping. Open checks for reviewers are listed under reviewNotes in scripts/data/thinking-tool-strategies.json.', '["No study found teaches analogy maps with a named break column to students under 11. Naming where an analogy breaks is untested at K-2 and 3-5, and grade 11 students mostly saw models as copies.","The 9-12 language-model map uses the Teacher''s Guide wording as an analogy under test. The Guide puts ''species'' and ''offspring'' in quotation marks. Neither Rahwan et al. nor Brinkmann et al. use species language for machines, and Rahwan et al. warn against excessive anthropomorphism and zoomorphism. S8 and S9 are cited for these limits and do not support the wording.","Selection, Inheritance and Scaffolding have no ''does not carry over'' note, so maps on them borrow the Fitness, Evolutionary Process, Domestication, Transmission, Learning or Teaching notes.","The K-2 robot station rests on small studies (six kindergartners in one, sixty children aged 4 to 7 in another)."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('94b01ad3-4fc0-5f7f-8af2-248e940e1f14', '401a0619-398d-5953-a61e-2e2d1bacf61f', '8363df74-ecd8-54e9-82f1-e93623f9995c', 1, 'K-2, Ideas That Are Like Other Ideas (precursor). Children put a known case and a new case side by side as picture cards and say what the new one reminds them of. They sort the features into same job, looks alike and different. An adult helps them name one difference, and relation words such as keeps safe help them see the shared job. Example: A bird''s nest and a child''s pillow fort, both built as a shelter. Shown as: Two picture cards and three sorting mats: same job, looks alike, different. New demand: Name one difference between two cases that share a job, as the Analogical Reasoning note asks. Relation words help; naming a break is untested at this age. Concepts: Analogical Reasoning, Variation. Domains: biology, culture, cognition.', '7c75aef6-b615-572a-aa01-b2c82591cd2f', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('89642e53-3804-5845-b0f4-9cc78d44d6a5', '401a0619-398d-5953-a61e-2e2d1bacf61f', '6f04ee30-2be3-537b-9d0e-b339d9fed79c', 2, 'K-2, Living Things Act to Meet Their Needs (precursor). Children compare an animal finding food with a toy robot rolling to its charger. On picture cards they sort what is the same (it ends up where it is needed) and what differs (a person built the robot and set its goal, from the Agency note). The teacher asks what rule the robot follows and records any answer that says it wants something. Example: A bird finding seeds and a toy robot rolling to its charger. Shown as: Two picture cards and a ''who set it up?'' sticker for each. New demand: Ask for the rule a machine follows when a child says it wants something. Easy tasks draw rule answers; harder tasks draw wants. Concepts: Agency, Theory of Mind, Analogical Reasoning, Technology. Domains: biology, technology, AI and computation.', '993c989a-79d2-5262-b20f-9636504623cd', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('9a8baeee-ddc0-5ec1-a0cd-a7aec0df9367', '401a0619-398d-5953-a61e-2e2d1bacf61f', 'db1fca08-0dcf-5910-a3df-2de902e8630a', 3, '3-5, Comparing Biological and Cultural Transmission (full). Students fill a two-column map: a trait passing from parent to child, and the rules of a game passing from one group of children to another. Rows: who holds it, who gets it, how it moves, what can change on the way, how exact the copy is. The break column uses the Transmission note on how exact each copy is. Example: Eye colour passing to a child, and a playground game''s rules passing to a new class. Shown as: Two-column table with five shared rows and a break column. New demand: Match on relations such as holder and receiver. Name one break taken from the Transmission note. Concepts: Transmission, Inheritance, Variation, Culture. Domains: biology, culture.', '0a1dc107-eeca-53a2-8a29-056c0f7b70df', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('fe2a116a-2efe-5c7d-b532-96f55a28e818', '401a0619-398d-5953-a61e-2e2d1bacf61f', '31b2be29-7a8c-5f98-a447-55ecf57f1ff9', 4, '3-5, Comparing How Different Living Things Act, Learn, and Teach (full). Students map three learners: a kitten learning to hunt, a child learning to read and a program that sorts photos after seeing labelled examples. Rows: what changes, what experience drives it, who sets the goal, who helps. Each break cell is filled from the Learning and Teaching notes. They also run a small sorting activity with labelled cards. Example: A kitten learning to hunt, a child learning to read and a photo-sorting program trained on labelled pictures. Shown as: Three-column table with four rows and a break cell for each pair. New demand: Three cases instead of two. Break cells compare the program with each living learner, taken from the Learning note. Concepts: Learning, Teaching, Agency. Domains: biology, cognition, education, AI and computation.', '241ac4b1-00b3-517c-b3b5-10029f1efdc6', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('013e3775-34b3-591a-88b3-d42e2bec9b31', '401a0619-398d-5953-a61e-2e2d1bacf61f', 'd2dc3119-7af8-55d8-8bfe-b63a4ec56acb', 5, '6-8, How Minds and Cultures Search for Better Ideas (full). Students map an essay revised over three drafts against a bird population changing over generations. Rows: what varies, what keeps or drops versions, what is passed on. The break column uses the Evolutionary Process note: one writer revising is not a population, the writer aims at a goal, and mutations ignore need. They list essay-side words that do not fit the birds. Example: A student revising an essay over three drafts and a bird population over many generations. Shown as: Two-column table with three relation rows and a break column with the concept named. New demand: Check the map against a second analogy, a breeder choosing animals, since one analogy can leave a wrong picture. Name where the first one fails. Concepts: Evolutionary Process, Metacognition, Search, Adaptation. Domains: cognition, education, biology.', '212e3ab0-5575-572b-89fe-cff0ab90594d', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('c4320a9e-a10c-5ff0-aedf-46b584b3915c', '401a0619-398d-5953-a61e-2e2d1bacf61f', 'ad0173a4-5c64-5d05-96ac-2b61810c4153', 6, '6-8, Culture as Transmitted, Institutions as Stabilizing Structures (full). Students compare three stand-ins for one school: a floor plan, a child''s mental picture and a robot''s stored grid of corridors. Rows: what is kept, what is left out, who treats it as a stand-in. The break column uses the Representation note: a map is not the territory, and a stored grid means nothing to the program alone. Example: A school floor plan, a child''s mental picture of the school and a robot''s stored corridor grid. Shown as: Three-column table with rows for kept, left out and who reads it. New demand: Say who treats each item as a stand-in and what each leaves out, then name a use for which each would fail. Concepts: Representation, Abstraction, Model, Information. Domains: culture, cognition, education, AI and computation.', 'fe387dcf-751c-59e6-9fa2-8fcc6abecea3', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('53e1a139-4475-5ce1-8fbb-ec807c357235', '401a0619-398d-5953-a61e-2e2d1bacf61f', 'ba60a3be-0135-5b53-b88f-a7aecfe0ed96', 7, '9-12, The Shared Structure of Discovery: Darwin''s Notebooks and the History of Science (extended). Students map three cases of selection: a breeder choosing pigeons, a wild finch population and a genetic algorithm. Rows: the variants, what keeps them, what passes on, who sets the target. The break column cites the Fitness, Evolutionary Process and Domestication notes, because Selection has none. They compare with Darwin''s use of the breeder analogy and check each wording for need-based phrases. Example: A breeder choosing pigeons, a wild finch population and a genetic algorithm, set beside Darwin''s use of the breeder analogy. Shown as: Three-column table with four rows and a break column that names the concept. New demand: Join three cases in one map and set it beside Darwin''s use of the breeder analogy. Name the wrong picture each single case would leave. Concepts: Analogical Reasoning, Selection, Domestication, Intuitive Theories. Domains: biology, culture, AI and computation.', '7c75aef6-b615-572a-aa01-b2c82591cd2f', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('acda81d7-c1c5-59e9-8f77-531bb7cff930', '401a0619-398d-5953-a61e-2e2d1bacf61f', '396e3dd9-4f22-5160-b6c7-3752caefa1b8', 8, '9-12, Selection Across Biology, Culture, Education, and AI (extended). Students test the Guide''s quoted words ''species'' and ''offspring'' for language models. They map species and offspring against model versions and derivatives, filling the break column first from the Descent, Population, Transmission and Evolutionary Process notes: mixed lines, no interbreeding, exact or imitated copies, people choosing which versions live. Then they keep or drop each word. Example: A tree of species beside a lineage of language-model versions, where one update can reach millions of copies at once. Shown as: Two-column table with the break column filled first and a keep-or-drop list of words. New demand: Fill the break column before the match column, then test the kept words on a second case, a family tree of tool designs. Keep a word only if it survives both. Concepts: Descent, Transmission, Selection Pressure, Population. Domains: biology, technology, AI and computation, culture.', 'e0a89c95-8625-539f-93ef-ac864737144a', 'Leads into the next use of the tool.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('c772a22d-92ed-5ca4-93c9-9bae6a787d07', '401a0619-398d-5953-a61e-2e2d1bacf61f', 'e820dc2d-9317-57d1-8475-22a701fc486a', 9, '9-12, Collective Intelligence, Distributed Cognition, and Coevolving Technology (extended). Students compare how a honeybee swarm picks a nest site with how a school council picks a rule. Rows: shared interest, who gathers information, how options are compared, how agreement is reached, who has influence. The break column uses the Collective Intelligence note: bees have no leader and no plan, and human groups can copy each other or follow a loud voice. Example: A honeybee swarm choosing a nest site and a school council choosing a rule. Shown as: Two-column table with the Guide''s decision principles as rows and a break column. New demand: Test each row for a hidden difference: planning, talk and written rules exist in the human column only. Concepts: Collective Intelligence, Role, Institutions, Communication. Domains: biology, culture.', '4e4ec762-ee46-53d3-afe3-da41c3d3f6af', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

UPDATE projects SET introduction = introduction || '

Thinking tools. Four OpenEvo thinking tools (Tinbergen''s Questions, Causal Mapping, Payoff Matrices and Analogy Mapping) are deployed across the grade bands of this space as four threads named "Thinking tool: ...". The aim is transfer across domains with an honest statement of where it stops. Analogy maps and Tinbergen''s grid ask one set of questions of biology, culture, technology, education, AI and computation, and cognition, and their break columns and empty rows come from the vocabulary''s ''does not carry over'' notes. Two 9-12 stations, a payoff table and a feed map, show that feedback, incentive and fitness change meaning by domain. The boundary forbids wants, intent or a family for machines. Every analogy map carries a break column. Analogy leads at K-2 and shares the lead at 3-5 with Tinbergen and Causal. Card comparisons grow into maps with a break column, while Causal and Payoff begin as arrow cards and outcome tables. At 6-8 Tinbergen and Causal share the lead, and Causal adds delays to the loops begun at 3-5. At 9-12 Tinbergen and Analogy share the lead with three or more senses, including machine behaviour and machine culture. Payoff tests choices from 6-8. The threads have the status proposed. AI drafted them and no subject expert has reviewed them.' WHERE id = '371fce26-d1f3-439b-95df-0a0e38b8a824' AND introduction NOT LIKE '%Thinking tools. Four OpenEvo thinking tools%';

